[[nodiscard]] LookStageUniforms make_look_stage_uniforms(
    const CompiledLookStageProgram& program,
    std::uint32_t pixel_count = 0U) {
  auto uniforms = LookStageUniforms{
      .luminance_coefficients = program.luminance_coefficients,
      .rgb_mixer = program.rgb_mixer,
      .black_and_white_mixer = program.black_and_white_mixer,
      .grading_hue = program.grading_hue,
      .grading_saturation = program.grading_saturation,
      .grading_luminance = program.grading_luminance,
      .mixer_hue = program.mixer_hue,
      .mixer_saturation = program.mixer_saturation,
      .mixer_luminance = program.mixer_luminance,
      .selective_cyan = program.selective_cyan,
      .selective_magenta = program.selective_magenta,
      .selective_yellow = program.selective_yellow,
      .selective_black = program.selective_black,
      .harmony_anchors = program.harmony_anchors,
      .saturation_strength = program.saturation_strength,
      .vibrance_strength = program.vibrance_strength,
      .grading_amount = program.grading_amount,
      .grading_balance = program.grading_balance,
      .harmony_strength = program.harmony_strength,
      .output_headroom = program.output_headroom,
      .replacement_source_hue = program.replacement_source_hue,
      .replacement_target_oklab_hue = program.replacement_target_oklab_hue,
      .replacement_range = program.replacement_range,
      .replacement_softness = program.replacement_softness,
      .replacement_strength = program.replacement_strength,
      .skin_hue = program.skin_hue,
      .skin_range = program.skin_range,
      .skin_strength = program.skin_strength,
      .mixer_model = program.mixer_model,
      .harmony_anchor_count = program.harmony_anchor_count,
      .replacement_preserve_luminance =
          program.replacement_preserve_luminance,
      .replacement_preserve_saturation =
          program.replacement_preserve_saturation,
      .active_mask = program.active_mask,
      .pixel_count = pixel_count,
  };
  for (auto index = std::size_t{0U}; index < 9U; ++index) {
    uniforms.rgb_to_xyz_d65[index] =
        static_cast<float>(program.rgb_to_xyz_d65.values[index]);
    uniforms.xyz_d65_to_rgb[index] =
        static_cast<float>(program.xyz_d65_to_rgb.values[index]);
  }
  return uniforms;
}

struct UserLutStageUniforms final {
  std::array<float, 9> working_to_input{};
  std::array<float, 9> output_to_working{};
  std::array<float, 3> domain_min{};
  std::array<float, 3> domain_max{};
  float strength = 0.0F;
  std::uint32_t input_transfer = 0U;
  std::uint32_t output_transfer = 0U;
  std::uint32_t lut_size = 0U;
  std::uint32_t pixel_count = 0U;
  float shaper_input_min = 0.0F;
  float shaper_input_max = 1.0F;
  std::uint32_t shaper_size = 0U;
  std::uint32_t shaper_offset = 0U;
};

[[nodiscard]] UserLutStageUniforms make_user_lut_stage_uniforms(
    const CompiledUserLut& user_lut, std::uint32_t pixel_count) {
  auto uniforms = UserLutStageUniforms{
      .strength = user_lut.strength,
      .input_transfer = static_cast<std::uint32_t>(user_lut.input_transfer),
      .output_transfer = static_cast<std::uint32_t>(user_lut.output_transfer),
      .lut_size = static_cast<std::uint32_t>(user_lut.lut.size),
      .pixel_count = pixel_count,
      .shaper_input_min = static_cast<float>(user_lut.lut.shaper_input_range[0]),
      .shaper_input_max = static_cast<float>(user_lut.lut.shaper_input_range[1]),
      .shaper_size = static_cast<std::uint32_t>(user_lut.lut.shaper_size),
      .shaper_offset = static_cast<std::uint32_t>(user_lut.lut.table.size()),
  };
  for (auto index = std::size_t{0U}; index < 9U; ++index) {
    uniforms.working_to_input[index] =
        static_cast<float>(user_lut.working_to_input.values[index]);
    uniforms.output_to_working[index] =
        static_cast<float>(user_lut.output_to_working.values[index]);
  }
  for (auto channel = std::size_t{0U}; channel < 3U; ++channel) {
    const auto minimum = user_lut.lut.domain_min[channel];
    const auto maximum = user_lut.lut.domain_max[channel];
    const auto valid = std::isfinite(minimum) && std::isfinite(maximum) &&
                       maximum > minimum;
    uniforms.domain_min[channel] = valid ? static_cast<float>(minimum) : 0.0F;
    uniforms.domain_max[channel] = valid ? static_cast<float>(maximum) : 1.0F;
  }
  return uniforms;
}

