static float3 multiply_matrix(constant float* matrix, float3 value) {
  return float3(
      matrix[0] * value.r + matrix[1] * value.g + matrix[2] * value.b,
      matrix[3] * value.r + matrix[4] * value.g + matrix[5] * value.b,
      matrix[6] * value.r + matrix[7] * value.g + matrix[8] * value.b);
}

static int lut_index(int size, int red, int green, int blue) {
  return (red * size + green) * size + blue;
}

static float3 tetrahedral_sample(
    device const float4* lut,
    int size,
    float3 coordinate) {
  float3 position = clamp(coordinate, 0.0f, 1.0f) * float(size - 1);
  int3 lower = min(int3(position), int3(size - 2));
  float3 f = position - float3(lower);
  float3 c000 = lut[lut_index(size, lower.r, lower.g, lower.b)].rgb;
  float3 c111 = lut[lut_index(size, lower.r + 1, lower.g + 1, lower.b + 1)].rgb;
  float3 v1;
  float3 v2;
  float4 weights;
  if (f.r >= f.g) {
    if (f.g >= f.b) {
      v1 = lut[lut_index(size, lower.r + 1, lower.g, lower.b)].rgb;
      v2 = lut[lut_index(size, lower.r + 1, lower.g + 1, lower.b)].rgb;
      weights = float4(1.0f - f.r, f.r - f.g, f.g - f.b, f.b);
    } else if (f.r >= f.b) {
      v1 = lut[lut_index(size, lower.r + 1, lower.g, lower.b)].rgb;
      v2 = lut[lut_index(size, lower.r + 1, lower.g, lower.b + 1)].rgb;
      weights = float4(1.0f - f.r, f.r - f.b, f.b - f.g, f.g);
    } else {
      v1 = lut[lut_index(size, lower.r, lower.g, lower.b + 1)].rgb;
      v2 = lut[lut_index(size, lower.r + 1, lower.g, lower.b + 1)].rgb;
      weights = float4(1.0f - f.b, f.b - f.r, f.r - f.g, f.g);
    }
  } else if (f.r >= f.b) {
    v1 = lut[lut_index(size, lower.r, lower.g + 1, lower.b)].rgb;
    v2 = lut[lut_index(size, lower.r + 1, lower.g + 1, lower.b)].rgb;
    weights = float4(1.0f - f.g, f.g - f.r, f.r - f.b, f.b);
  } else if (f.g >= f.b) {
    v1 = lut[lut_index(size, lower.r, lower.g + 1, lower.b)].rgb;
    v2 = lut[lut_index(size, lower.r, lower.g + 1, lower.b + 1)].rgb;
    weights = float4(1.0f - f.g, f.g - f.b, f.b - f.r, f.r);
  } else {
    v1 = lut[lut_index(size, lower.r, lower.g, lower.b + 1)].rgb;
    v2 = lut[lut_index(size, lower.r, lower.g + 1, lower.b + 1)].rgb;
    weights = float4(1.0f - f.b, f.b - f.g, f.g - f.r, f.r);
  }
  return c000 * weights.x + v1 * weights.y + v2 * weights.z +
         c111 * weights.w;
}

static float3 apply_black_point_compensation(
    float3 value,
    constant Aces2OutputLutUniforms& uniforms) {
  if (uniforms.black_point_compensation_enabled == 0) {
    return value;
  }
  float source_span = max(1.0e-6f, uniforms.black_point_headroom -
                                      uniforms.source_black_point);
  float output_span = max(0.0f, uniforms.black_point_headroom -
                                    uniforms.output_black_point);
  float3 normalized = (value - uniforms.source_black_point) / source_span;
  float3 remapped = uniforms.output_black_point + normalized * output_span;
  return select(
      clamp(remapped, 0.0f, uniforms.black_point_headroom),
      float3(uniforms.output_black_point),
      value <= uniforms.source_black_point);
}

static float4 apply_aces2_output_pixel(
    float4 source,
    device const float4* lut,
    constant Aces2OutputLutUniforms& uniforms) {
  float3 acescg = multiply_matrix(uniforms.working_to_acescg, source.rgb);
  acescg = clamp(acescg, 0.0f, uniforms.shaper_maximum);
  float denominator = log(1.0f + uniforms.shaper_maximum /
                                     uniforms.shaper_offset);
  float3 coordinate = log(1.0f + acescg / uniforms.shaper_offset) /
                      denominator;
  float3 target = tetrahedral_sample(lut, uniforms.lut_size, coordinate);
  target = clamp(target, 0.0f, uniforms.maximum_physical_rgb) *
           uniforms.physical_to_reference_white;
  target = apply_black_point_compensation(target, uniforms);
  target = clamp(target, 0.0f, uniforms.display_headroom);
  return float4(target, clamp(source.a, 0.0f, 1.0f));
}

static float3 linear_to_srgb(float3 value) {
  value = clamp(value, 0.0f, 1.0f);
  return select(
      1.055f * pow(value, float3(1.0f / 2.4f)) - 0.055f,
      12.92f * value,
      value <= 0.0031308f);
}

kernel void apply_aces2_output_lut(
    device float4* pixels [[buffer(0)]],
    device const float4* lut [[buffer(1)]],
    constant Aces2OutputLutUniforms& uniforms [[buffer(2)]],
    uint gid [[thread_position_in_grid]]) {
  uint count = uint(uniforms.width) * uint(uniforms.height);
  if (gid >= count) {
    return;
  }
  pixels[gid] = apply_aces2_output_pixel(pixels[gid], lut, uniforms);
}

kernel void apply_aces2_output_lut_target(
    device const float4* source [[buffer(0)]],
    device float4* destination [[buffer(1)]],
    device const float4* lut [[buffer(2)]],
    constant Aces2OutputLutUniforms& uniforms [[buffer(3)]],
    uint gid [[thread_position_in_grid]]) {
  uint count = uint(uniforms.width) * uint(uniforms.height);
  if (gid >= count) return;
  destination[gid] = apply_aces2_output_pixel(source[gid], lut, uniforms);
}

kernel void publish_aces2_output_lut_srgb8(
    device const float4* pixels [[buffer(0)]],
    device const float4* lut [[buffer(1)]],
    constant Aces2OutputLutUniforms& uniforms [[buffer(2)]],
    texture2d<float, access::write> output [[texture(0)]],
    uint2 gid [[thread_position_in_grid]]) {
  if (gid.x >= uint(uniforms.width) || gid.y >= uint(uniforms.height)) {
    return;
  }
  uint index = (gid.y + uint(uniforms.source_origin_y)) *
                   uint(uniforms.source_width) +
               gid.x + uint(uniforms.source_origin_x);
  float4 target = apply_aces2_output_pixel(pixels[index], lut, uniforms);
  output.write(float4(linear_to_srgb(target.rgb), target.a), gid);
}
)";
}

[[nodiscard]] NSString* icc_transform_lut_shader_source() {
  return @R"(
#include <metal_stdlib>
using namespace metal;

struct IccTransformLutUniforms {
  float input_shaper_exponent;
  int lut_size;
  int width;
  int height;
};

static int icc_lut_index(int size, int red, int green, int blue) {
  return (red * size + green) * size + blue;
}

static float3 icc_tetrahedral_sample(
    device const float4* lut,
    int size,
    float3 coordinate) {
  float3 position = clamp(coordinate, 0.0f, 1.0f) * float(size - 1);
  int3 lower = min(int3(position), int3(size - 2));
  float3 f = position - float3(lower);
  float3 c000 = lut[icc_lut_index(size, lower.r, lower.g, lower.b)].rgb;
  float3 c111 = lut[icc_lut_index(
      size, lower.r + 1, lower.g + 1, lower.b + 1)].rgb;
  float3 v1;
  float3 v2;
  float4 weights;
  if (f.r >= f.g) {
    if (f.g >= f.b) {
      v1 = lut[icc_lut_index(size, lower.r + 1, lower.g, lower.b)].rgb;
      v2 = lut[icc_lut_index(size, lower.r + 1, lower.g + 1, lower.b)].rgb;
      weights = float4(1.0f - f.r, f.r - f.g, f.g - f.b, f.b);
    } else if (f.r >= f.b) {
      v1 = lut[icc_lut_index(size, lower.r + 1, lower.g, lower.b)].rgb;
      v2 = lut[icc_lut_index(size, lower.r + 1, lower.g, lower.b + 1)].rgb;
      weights = float4(1.0f - f.r, f.r - f.b, f.b - f.g, f.g);
    } else {
      v1 = lut[icc_lut_index(size, lower.r, lower.g, lower.b + 1)].rgb;
      v2 = lut[icc_lut_index(size, lower.r + 1, lower.g, lower.b + 1)].rgb;
      weights = float4(1.0f - f.b, f.b - f.r, f.r - f.g, f.g);
    }
  } else if (f.r >= f.b) {
    v1 = lut[icc_lut_index(size, lower.r, lower.g + 1, lower.b)].rgb;
    v2 = lut[icc_lut_index(size, lower.r + 1, lower.g + 1, lower.b)].rgb;
    weights = float4(1.0f - f.g, f.g - f.r, f.r - f.b, f.b);
  } else if (f.g >= f.b) {
    v1 = lut[icc_lut_index(size, lower.r, lower.g + 1, lower.b)].rgb;
    v2 = lut[icc_lut_index(size, lower.r, lower.g + 1, lower.b + 1)].rgb;
    weights = float4(1.0f - f.g, f.g - f.b, f.b - f.r, f.r);
  } else {
    v1 = lut[icc_lut_index(size, lower.r, lower.g, lower.b + 1)].rgb;
    v2 = lut[icc_lut_index(size, lower.r, lower.g + 1, lower.b + 1)].rgb;
    weights = float4(1.0f - f.b, f.b - f.g, f.g - f.r, f.r);
  }
  return c000 * weights.x + v1 * weights.y + v2 * weights.z +
         c111 * weights.w;
}

kernel void apply_icc_transform_lut(
    device float4* pixels [[buffer(0)]],
    device const float4* lut [[buffer(1)]],
    device const uchar* unsafe_cells [[buffer(2)]],
    constant IccTransformLutUniforms& uniforms [[buffer(3)]],
    uint gid [[thread_position_in_grid]]) {
  uint count = uint(uniforms.width) * uint(uniforms.height);
  if (gid >= count) {
    return;
  }
  float4 source = pixels[gid];
  if (any(source.rgb < 0.0f) || any(source.rgb > 1.0f)) {
    return;
  }
  float3 coordinate = pow(source.rgb, uniforms.input_shaper_exponent);
  int cell_size = uniforms.lut_size - 1;
  int3 cell = min(int3(coordinate * float(cell_size)), int3(cell_size - 1));
  if (unsafe_cells[icc_lut_index(cell_size, cell.r, cell.g, cell.b)] != 0) {
    return;
  }
  float3 output = icc_tetrahedral_sample(
      lut, uniforms.lut_size, coordinate);
  pixels[gid] = float4(output, source.a);
}

kernel void publish_icc_transform_lut_bgra8(
    device const float4* pixels [[buffer(0)]],
    device const float4* lut [[buffer(1)]],
    constant IccTransformLutUniforms& uniforms [[buffer(2)]],
    texture2d<float, access::write> output_texture [[texture(0)]],
    uint2 gid [[thread_position_in_grid]]) {
  if (gid.x >= uint(uniforms.width) || gid.y >= uint(uniforms.height)) {
    return;
  }
  uint index = gid.y * uint(uniforms.width) + gid.x;
  float4 source = pixels[index];
  float3 coordinate = pow(clamp(source.rgb, 0.0f, 1.0f),
                          uniforms.input_shaper_exponent);
  float3 output = icc_tetrahedral_sample(
      lut, uniforms.lut_size, coordinate);
  output_texture.write(float4(output, source.a), gid);
}

inline bool icc_pixel_requires_exact_transform(
    float4 source,
    device const uchar* unsafe_cells,
    constant IccTransformLutUniforms& uniforms) {
  if (any(!isfinite(source)) || any(source.rgb < 0.0f) ||
      any(source.rgb > 1.0f)) {
    return true;
  }
  float3 coordinate = pow(source.rgb, uniforms.input_shaper_exponent);
  int cell_size = uniforms.lut_size - 1;
  int3 cell = min(int3(coordinate * float(cell_size)), int3(cell_size - 1));
  return unsafe_cells[icc_lut_index(
      cell_size, cell.r, cell.g, cell.b)] != 0;
}

kernel void count_icc_exact_fallback_pixels(
    device const float4* pixels [[buffer(0)]],
    device const uchar* unsafe_cells [[buffer(1)]],
    constant IccTransformLutUniforms& uniforms [[buffer(2)]],
    device atomic_uint* exact_count [[buffer(3)]],
    uint gid [[thread_position_in_grid]]) {
  uint count = uint(uniforms.width) * uint(uniforms.height);
  if (gid < count && icc_pixel_requires_exact_transform(
                         pixels[gid], unsafe_cells, uniforms)) {
    atomic_fetch_add_explicit(exact_count, 1u, memory_order_relaxed);
  }
}

kernel void compact_icc_exact_fallback_pixels(
    device const float4* pixels [[buffer(0)]],
    device const uchar* unsafe_cells [[buffer(1)]],
    constant IccTransformLutUniforms& uniforms [[buffer(2)]],
    device atomic_uint* exact_count [[buffer(3)]],
    device float4* exact_pixels [[buffer(4)]],
    device uint* exact_indices [[buffer(5)]],
    uint gid [[thread_position_in_grid]]) {
  uint count = uint(uniforms.width) * uint(uniforms.height);
  if (gid >= count || !icc_pixel_requires_exact_transform(
                          pixels[gid], unsafe_cells, uniforms)) {
    return;
  }
  uint compact_index = atomic_fetch_add_explicit(
      exact_count, 1u, memory_order_relaxed);
  exact_pixels[compact_index] = pixels[gid];
  exact_indices[compact_index] = gid;
}

kernel void patch_icc_exact_fallback_bgra8(
    device const float4* exact_pixels [[buffer(0)]],
    device const uint* exact_indices [[buffer(1)]],
    constant uint& exact_count [[buffer(2)]],
    constant uint& width [[buffer(3)]],
    texture2d<float, access::write> output_texture [[texture(0)]],
    uint gid [[thread_position_in_grid]]) {
  if (gid >= exact_count) {
    return;
  }
  uint pixel_index = exact_indices[gid];
  uint2 coordinate = uint2(pixel_index % width, pixel_index / width);
  output_texture.write(exact_pixels[gid], coordinate);
}
)";
}

std::array<int, 3> gaussian_approximation_radii(double sigma) {
  if (sigma <= 0.0) {
    return {0, 0, 0};
  }

  constexpr int kPassCount = 3;
  const auto ideal_width = std::sqrt((12.0 * sigma * sigma / static_cast<double>(kPassCount)) + 1.0);
  auto lower_width = static_cast<int>(std::floor(ideal_width));
  if ((lower_width % 2) == 0) {
    --lower_width;
  }
  lower_width = std::max(1, lower_width);
  const auto upper_width = lower_width + 2;
  const auto lower_count = std::clamp(static_cast<int>(std::round(
      (12.0 * sigma * sigma -
       static_cast<double>(kPassCount * lower_width * lower_width) -
       static_cast<double>(4 * kPassCount * lower_width) -
       static_cast<double>(3 * kPassCount)) /
      static_cast<double>(-4 * lower_width - 4))), 0, kPassCount);

  std::array<int, 3> radii{};
  for (int pass = 0; pass < kPassCount; ++pass) {
    const auto width = pass < lower_count ? lower_width : upper_width;
    radii[static_cast<std::size_t>(pass)] = std::max(0, (width - 1) / 2);
  }
  return radii;
}

MaskUniforms make_mask_uniforms(const ColorAdjustmentState& state, int width, int height) {
  const auto linear_wb = preview_white_balance_multipliers(
      state.linear_mask_temperature, 0.0);
  const auto radial_wb = preview_white_balance_multipliers(
      state.radial_mask_temperature, 0.0);

  MaskUniforms uniforms{};
  uniforms.has_linear_mask = state.linear_mask_enabled ? 1 : 0;
  uniforms.linear_exposure = static_cast<float>(state.linear_mask_exposure);
  uniforms.linear_temperature = static_cast<float>(state.linear_mask_temperature);
  uniforms.linear_feather = static_cast<float>(state.linear_mask_feather);
  uniforms.linear_position = static_cast<float>(state.linear_mask_position);
  uniforms.linear_rotation_rad = static_cast<float>(state.linear_mask_rotation * kPi / 180.0);
  uniforms.linear_wb_red = static_cast<float>(linear_wb[0]);
  uniforms.linear_wb_green = static_cast<float>(linear_wb[1]);
  uniforms.linear_wb_blue = static_cast<float>(linear_wb[2]);
  uniforms.has_radial_mask = state.radial_mask_enabled ? 1 : 0;
  uniforms.radial_exposure = static_cast<float>(state.radial_mask_exposure);
  uniforms.radial_temperature = static_cast<float>(state.radial_mask_temperature);
  uniforms.radial_feather = static_cast<float>(state.radial_mask_feather);
  uniforms.radial_center_x = static_cast<float>(state.radial_mask_center_x);
  uniforms.radial_center_y = static_cast<float>(state.radial_mask_center_y);
  uniforms.radial_radius_x = static_cast<float>(state.radial_mask_radius_x);
  uniforms.radial_radius_y = static_cast<float>(state.radial_mask_radius_y);
  uniforms.radial_rotation_rad = static_cast<float>(state.radial_mask_rotation * kPi / 180.0);
  uniforms.radial_wb_red = static_cast<float>(radial_wb[0]);
  uniforms.radial_wb_green = static_cast<float>(radial_wb[1]);
  uniforms.radial_wb_blue = static_cast<float>(radial_wb[2]);
  uniforms.width = width;
  uniforms.height = height;
  return uniforms;
}

Aces2OutputLutUniforms make_aces2_output_lut_uniforms(
    const CompiledAces2OutputLutApplication& application,
    int width,
    int height,
    int source_width = 0,
    int source_origin_x = 0,
    int source_origin_y = 0) {
  const auto& lut = *application.lut;
  const auto safe_black_headroom =
      std::clamp(application.black_point_headroom, 1.0, 16.0);
  const auto safe_display_headroom =
      std::clamp(application.display_headroom, 1.0, 100.0);
  const auto maximum_black = std::max(0.0, safe_black_headroom - 1.0e-6);
  const auto safe_source_black = std::clamp(
      application.source_black_point, 0.0, maximum_black);
  const auto safe_output_black = std::clamp(
      application.output_black_point, 0.0, maximum_black);
  Aces2OutputLutUniforms uniforms{};
  for (std::size_t index = 0U; index < 9U; ++index) {
    uniforms.working_to_acescg[index] =
        static_cast<float>(lut.working_to_acescg.values[index]);
  }
  uniforms.shaper_maximum = static_cast<float>(lut.shaper_maximum);
  uniforms.shaper_offset = static_cast<float>(lut.settings.shaper_offset);
  uniforms.maximum_physical_rgb = static_cast<float>(lut.maximum_physical_rgb);
  uniforms.physical_to_reference_white =
      static_cast<float>(lut.physical_to_reference_white);
  uniforms.source_black_point = static_cast<float>(safe_source_black);
  uniforms.output_black_point = static_cast<float>(safe_output_black);
  uniforms.black_point_headroom = static_cast<float>(safe_black_headroom);
  uniforms.display_headroom = static_cast<float>(safe_display_headroom);
  uniforms.black_point_compensation_enabled =
      application.black_point_compensation_enabled &&
              std::abs(safe_source_black - safe_output_black) > 1.0e-9
          ? 1
          : 0;
  uniforms.lut_size = lut.settings.cube_size;
  uniforms.width = width;
  uniforms.height = height;
  uniforms.source_width = source_width > 0 ? source_width : width;
  uniforms.source_origin_x = source_origin_x;
  uniforms.source_origin_y = source_origin_y;
  return uniforms;
}

RenderSurfaceDescriptor srgb8_output_descriptor(
    int width,
    int height) {
  return RenderSurfaceDescriptor{
      .pixel_encoding = RenderPixelEncoding::DisplayEncodedFloat,
      .color_domain = RenderColorDomain::Device,
      .range = RenderRangeModel::DisplayBounded,
      .alpha = RenderAlphaModel::Straight,
      .color_space_identity = "sRGB",
      .transfer_identity = "srgb",
      .width = static_cast<std::uint32_t>(std::max(width, 0)),
      .height = static_cast<std::uint32_t>(std::max(height, 0)),
  };
}

void copy_pixels_to_float_buffer(float* destination, const std::vector<ColorPixel>& pixels) {
  std::memcpy(destination, pixels.data(), pixels.size() * sizeof(ColorPixel));
}

[[nodiscard]] bool icc_lut_pixel_safe(
    const IccTransformLut3D& lut,
    const ColorPixel& pixel) {
  if (pixel.red < 0.0F || pixel.red > 1.0F || pixel.green < 0.0F ||
      pixel.green > 1.0F || pixel.blue < 0.0F || pixel.blue > 1.0F) {
    return false;
  }
  const auto cell_size = lut.settings.cube_size - 1;
  const auto coordinate = [&](float value) {
    const auto encoded = std::pow(
        static_cast<double>(value),
        lut.settings.input_shaper_exponent);
    return std::min(
        static_cast<int>(encoded * static_cast<double>(cell_size)),
        cell_size - 1);
  };
  const auto red = coordinate(pixel.red);
  const auto green = coordinate(pixel.green);
  const auto blue = coordinate(pixel.blue);
  const auto safe_size = static_cast<std::size_t>(cell_size);
  const auto index =
      (static_cast<std::size_t>(red) * safe_size +
       static_cast<std::size_t>(green)) *
          safe_size +
      static_cast<std::size_t>(blue);
  return lut.unsafe_cells[index] == 0U;
}

