static float3 user_lut_multiply(constant float* m,float3 v){return float3(m[0]*v.r+m[1]*v.g+m[2]*v.b,
    m[3]*v.r+m[4]*v.g+m[5]*v.b,m[6]*v.r+m[7]*v.g+m[8]*v.b);}
