  destination[gid]=float4(corrected.rgb,clamp(corrected.a,0.0f,1.0f));}

static float retained_spatial_luminance(float3 rgb,constant RetainedSpatialDetailUniforms& u){
  return rgb.r*u.luminance_red+rgb.g*u.luminance_green+rgb.b*u.luminance_blue;}
static float retained_spatial_bell_weight(float value,float center,float radius){if(radius<=0.0f)return 0.0f;
  float distance=abs(value-center)/radius;if(distance>=1.0f)return 0.0f;float amount=1.0f-distance;return amount*amount*(3.0f-2.0f*amount);}
static float4 retained_spatial_scale_to_luminance(float4 source,float target,constant RetainedSpatialDetailUniforms& u){
  float source_luminance=retained_spatial_luminance(source.rgb,u),maximum_channel=max(source.r,max(source.g,source.b));
  float safe_target=max(0.0f,target);if(maximum_channel<=1.0e-9f||source_luminance<=1.0e-9f)safe_target=min(safe_target,u.output_headroom);
  else safe_target=min(safe_target,max(0.0f,u.output_headroom*source_luminance/maximum_channel));
  float maximum_magnitude=max(abs(source.r),max(abs(source.g),abs(source.b)));float3 adjusted=source.rgb;
  if(maximum_magnitude<=1.0e-9f)adjusted=float3(safe_target);else if(source_luminance>1.0e-6f)adjusted*=safe_target/source_luminance;
  float adjusted_luminance=max(0.0f,retained_spatial_luminance(adjusted,u)),nonnegative_source=max(0.0f,source_luminance);
  float lift_stops=log2((adjusted_luminance+1.0e-6f)/(nonnegative_source+1.0e-6f));if(lift_stops>0.0f){
    float spread=max(abs(source.r-source.g),max(abs(source.g-source.b),abs(source.r-source.b)));
    float attenuation=clamp((1.0f-smoothstep(0.012f,0.16f,nonnegative_source))*smoothstep(0.12f,1.20f,lift_stops)*
        (1.0f-smoothstep(0.025f,0.12f,spread))*0.56f,0.0f,0.56f);
    adjusted=adjusted_luminance+(adjusted-adjusted_luminance)*(1.0f-attenuation);}return float4(adjusted,source.a);}
kernel void extract_retained_spatial_luminance(device const float4* pixels [[buffer(0)]],device float* luminance_buffer [[buffer(1)]],
    constant RetainedSpatialDetailUniforms& u [[buffer(2)]],uint gid [[thread_position_in_grid]]){
  if(gid>=u.width*u.height)return;luminance_buffer[gid]=retained_spatial_luminance(pixels[gid].rgb,u);}
kernel void apply_retained_spatial_detail(device float4* pixels [[buffer(0)]],device const float* luminance_buffer [[buffer(1)]],
    device const float* texture_blur [[buffer(2)]],device const float* clarity_blur [[buffer(3)]],device const float* haze_blur [[buffer(4)]],
    constant RetainedSpatialDetailUniforms& u [[buffer(5)]],uint gid [[thread_position_in_grid]]){
  if(gid>=u.width*u.height)return;uint x=gid%u.width,y=gid/u.width;float luminance=luminance_buffer[gid],local_activity=0.0f;
  if(x>0u)local_activity=max(local_activity,abs(luminance-luminance_buffer[gid-1u]));if(x+1u<u.width)local_activity=max(local_activity,abs(luminance-luminance_buffer[gid+1u]));
  if(y>0u)local_activity=max(local_activity,abs(luminance-luminance_buffer[gid-u.width]));if(y+1u<u.height)local_activity=max(local_activity,abs(luminance-luminance_buffer[gid+u.width]));
  float midtone=retained_spatial_bell_weight(luminance,0.5f,0.42f),shadow=smoothstep(0.025f,0.12f,luminance);
  float highlight=1.0f-smoothstep(0.74f,0.98f,luminance),tone_guard=shadow*highlight,target=luminance;
  if((u.active_mask&1u)!=0u){float signal=luminance-texture_blur[gid],broad=(u.active_mask&2u)!=0u?luminance-clarity_blur[gid]:local_activity;
    float guard=1.0f-smoothstep(0.08f,0.36f,abs(broad))*0.72f,gain=u.texture_strength>=0.0f?1.30f:0.48f;
    target+=u.texture_strength*signal*(0.46f+midtone*0.70f)*guard*tone_guard*gain;}
  if((u.active_mask&2u)!=0u){float signal=luminance-clarity_blur[gid],edge=1.0f-smoothstep(0.24f,0.58f,abs(signal))*0.28f;
    float structure=smoothstep(0.003f,0.035f,local_activity),gain=u.clarity_strength>=0.0f?1.08f:0.46f;
    target+=u.clarity_strength*signal*(0.36f+midtone*0.82f)*tone_guard*edge*structure*gain;}
  if((u.active_mask&4u)!=0u){float signal=clamp(luminance-haze_blur[gid],-0.18f,0.18f),activity=smoothstep(0.0015f,0.018f,local_activity);
    float edge=1.0f-smoothstep(0.11f,0.18f,abs(signal))*0.95f,gain=u.dehaze_strength>=0.0f?0.95f:0.36f;
    target+=u.dehaze_strength*signal*(0.52f+midtone*0.78f)*highlight*activity*edge*gain;
    float shadow_weight=1.0f-smoothstep(0.08f,0.20f,luminance),structure=smoothstep(0.008f,0.065f,abs(signal))*activity*edge;
    if(u.dehaze_strength>0.0f){target*=max(0.0f,1.0f-u.dehaze_strength*shadow_weight*structure*0.52f);
      target*=max(0.0f,1.0f-u.dehaze_strength*shadow_weight*activity*edge*0.035f);}
    else target+=(-u.dehaze_strength)*shadow_weight*structure*0.075f;}
  pixels[gid]=retained_spatial_scale_to_luminance(pixels[gid],target,u);}

static float3 retained_detail_multiply(constant float* m,float3 v){return float3(m[0]*v.r+m[1]*v.g+m[2]*v.b,
    m[3]*v.r+m[4]*v.g+m[5]*v.b,m[6]*v.r+m[7]*v.g+m[8]*v.b);}
static float retained_detail_cbrt(float v){return copysign(pow(abs(v),1.0f/3.0f),v);}
static float3 retained_detail_rgb_to_oklab(float3 rgb,constant RetainedFineDetailUniforms& u){float3 xyz=retained_detail_multiply(u.rgb_to_xyz_d65,rgb);
  float l=0.8189330101f*xyz.x+0.3618667424f*xyz.y-0.1288597137f*xyz.z,m=0.0329845436f*xyz.x+0.9293118715f*xyz.y+0.0361456387f*xyz.z;
  float s=0.0482003018f*xyz.x+0.2643662691f*xyz.y+0.6338517070f*xyz.z,lr=retained_detail_cbrt(l),mr=retained_detail_cbrt(m),sr=retained_detail_cbrt(s);
  return float3(0.2104542553f*lr+0.7936177850f*mr-0.0040720468f*sr,1.9779984951f*lr-2.4285922050f*mr+0.4505937099f*sr,
      0.0259040371f*lr+0.7827717662f*mr-0.8086757660f*sr);}
static float3 retained_detail_oklab_to_rgb(float lightness,float a,float b,constant RetainedFineDetailUniforms& u){
  float lr=lightness+0.3963377774f*a+0.2158037573f*b,mr=lightness-0.1055613458f*a-0.0638541728f*b,sr=lightness-0.0894841775f*a-1.2914855480f*b;
  float l=lr*lr*lr,m=mr*mr*mr,s=sr*sr*sr;float3 xyz=float3(1.2270138511f*l-0.5577999807f*m+0.2812561490f*s,
      -0.0405801784f*l+1.1122568696f*m-0.0716766787f*s,-0.0763812845f*l-0.4214819784f*m+1.5861632204f*s);
  return retained_detail_multiply(u.xyz_d65_to_rgb,xyz);}
kernel void extract_retained_fine_detail(device const float4* pixels [[buffer(0)]],device float* lightness [[buffer(1)]],
    device float* chroma_a [[buffer(2)]],device float* chroma_b [[buffer(3)]],constant RetainedFineDetailUniforms& u [[buffer(4)]],
    uint gid [[thread_position_in_grid]]){if(gid>=u.width*u.height)return;float3 lab=retained_detail_rgb_to_oklab(pixels[gid].rgb,u);
  lightness[gid]=lab.x;chroma_a[gid]=lab.y;chroma_b[gid]=lab.z;}
kernel void apply_retained_sharpen(device float* lightness [[buffer(0)]],device const float* sharp_blur [[buffer(1)]],
    device const float* edge_blur [[buffer(2)]],constant RetainedFineDetailUniforms& u [[buffer(3)]],uint gid [[thread_position_in_grid]]){
  if(gid>=u.width*u.height)return;float signal=lightness[gid]-sharp_blur[gid],gate=1.0f;if(u.sharpen_mask_strength>1.0e-6f)
    gate=smoothstep(0.0015f,0.012f+0.06f*u.sharpen_mask_strength,abs(lightness[gid]-edge_blur[gid]));
  lightness[gid]+=signal*u.sharpen_strength*u.sharpen_gain*gate;}
kernel void apply_retained_luminance_nr(device float* lightness [[buffer(0)]],device const float* nr_blur [[buffer(1)]],
    device const float* edge_blur [[buffer(2)]],constant RetainedFineDetailUniforms& u [[buffer(3)]],uint gid [[thread_position_in_grid]]){
  if(gid>=u.width*u.height)return;float edge=abs(lightness[gid]-edge_blur[gid]),preserve=1.0f-smoothstep(0.005f,0.04f,edge);
  lightness[gid]=mix(lightness[gid],nr_blur[gid],u.luminance_nr_strength*0.85f*preserve);}
kernel void apply_retained_color_nr(device float* chroma_a [[buffer(0)]],device float* chroma_b [[buffer(1)]],
    device const float* a_blur [[buffer(2)]],device const float* b_blur [[buffer(3)]],constant RetainedFineDetailUniforms& u [[buffer(4)]],
    uint gid [[thread_position_in_grid]]){if(gid>=u.width*u.height)return;float blend=u.color_nr_strength*0.90f;
  chroma_a[gid]=mix(chroma_a[gid],a_blur[gid],blend);chroma_b[gid]=mix(chroma_b[gid],b_blur[gid],blend);}
kernel void compose_retained_fine_detail(device float4* pixels [[buffer(0)]],device const float* lightness [[buffer(1)]],
    device const float* chroma_a [[buffer(2)]],device const float* chroma_b [[buffer(3)]],constant RetainedFineDetailUniforms& u [[buffer(4)]],
    uint gid [[thread_position_in_grid]]){if(gid>=u.width*u.height)return;pixels[gid]=float4(retained_detail_oklab_to_rgb(
      lightness[gid],chroma_a[gid],chroma_b[gid],u),pixels[gid].a);}

struct MaskUniforms {
  int has_linear_mask; float linear_exposure; float linear_temperature; float linear_feather;
  float linear_position; float linear_rotation_rad;
  int has_radial_mask; float radial_exposure; float radial_temperature; float radial_feather;
  float radial_center_x; float radial_center_y; float radial_radius_x; float radial_radius_y;
  float radial_rotation_rad;
  float radial_wb_red; float radial_wb_green; float radial_wb_blue;
  float linear_wb_red; float linear_wb_green; float linear_wb_blue;
  int width; int height;
};

struct BlurUniforms {
  int width; int height; int radius;
};
struct GuidedFilterUniforms { uint pixel_count; float epsilon; };

kernel void apply_masks(device float4* pixels [[buffer(0)]], constant MaskUniforms& u [[buffer(1)]],
    uint gid [[thread_position_in_grid]]) {
  if (gid >= uint(u.width) * uint(u.height)) return;
  int x = int(gid) % u.width, y = int(gid) / u.width;
  float nx = u.width > 1 ? float(x) / float(u.width - 1) : 0.5f;
  float ny = u.height > 1 ? float(y) / float(u.height - 1) : 0.5f;
  float4 p = pixels[gid];
  if (u.has_linear_mask) {
    float cr = cos(u.linear_rotation_rad), sr = sin(u.linear_rotation_rad);
    float axis = (nx - 0.5f) * cr + (ny - 0.5f) * sr + 0.5f;
    float w = clamp_unit((u.linear_position - axis) / max(0.05f, u.linear_feather) + 0.5f);
    if (w > 0.0f) { float g = pow(2.0f, u.linear_exposure * w);
      p.r *= (1.0f + (u.linear_wb_red - 1.0f) * w) * g;
      p.g *= (1.0f + (u.linear_wb_green - 1.0f) * w) * g;
      p.b *= (1.0f + (u.linear_wb_blue - 1.0f) * w) * g; }
  }
  if (u.has_radial_mask) {
    float cr = cos(u.radial_rotation_rad), sr = sin(u.radial_rotation_rad);
    float2 t = float2(nx, ny) - float2(u.radial_center_x, u.radial_center_y);
    float lx = t.x * cr + t.y * sr, ly = -t.x * sr + t.y * cr;
    float2 sr2 = max(float2(u.radial_radius_x, u.radial_radius_y), float2(0.05f));
    float d = sqrt(lx*lx/(sr2.x*sr2.x) + ly*ly/(sr2.y*sr2.y));
    float inner = max(0.0f, 1.0f - clamp(u.radial_feather, 0.05f, 1.0f));
    float w = 0.0f;
    if (d <= inner) w = 1.0f;
    else if (d < 1.0f) { float s = clamp_unit((d - inner) / (1.0f - inner)); w = 1.0f - s*s*(3.0f-2.0f*s); }
    if (w > 0.0f) { float g = pow(2.0f, u.radial_exposure * w);
      p.r *= (1.0f + (u.radial_wb_red - 1.0f) * w) * g;
      p.g *= (1.0f + (u.radial_wb_green - 1.0f) * w) * g;
      p.b *= (1.0f + (u.radial_wb_blue - 1.0f) * w) * g; }
  }
  pixels[gid] = max(p, float4(0.0f));
}

kernel void box_blur_horizontal(device const float* input [[buffer(0)]], device float* output [[buffer(1)]],
    constant BlurUniforms& u [[buffer(2)]], uint gid [[thread_position_in_grid]]) {
  if (gid >= uint(u.width) * uint(u.height)) return;
  int x = int(gid) % u.width, y = int(gid) / u.width;
  int kernel_width = u.radius * 2 + 1;
  float sum = 0.0f;
  for (int sample = -u.radius; sample <= u.radius; ++sample) {
    int clamped_x = clamp(x + sample, 0, u.width - 1);
    sum += input[y * u.width + clamped_x];
  }
  output[gid] = sum / float(kernel_width);
}

kernel void box_blur_vertical(device const float* input [[buffer(0)]], device float* output [[buffer(1)]],
    constant BlurUniforms& u [[buffer(2)]], uint gid [[thread_position_in_grid]]) {
  if (gid >= uint(u.width) * uint(u.height)) return;
  int x = int(gid) % u.width, y = int(gid) / u.width;
  int kernel_width = u.radius * 2 + 1;
  float sum = 0.0f;
  for (int sample = -u.radius; sample <= u.radius; ++sample) {
    int clamped_y = clamp(y + sample, 0, u.height - 1);
    sum += input[clamped_y * u.width + x];
  }
  output[gid] = sum / float(kernel_width);
}
kernel void retained_guided_square(device const float* input [[buffer(0)]],device float* correlation [[buffer(1)]],
    constant GuidedFilterUniforms& u [[buffer(2)]],uint gid [[thread_position_in_grid]]){
  if(gid>=u.pixel_count)return;correlation[gid]=input[gid]*input[gid];}
kernel void retained_guided_coefficients(device const float* input [[buffer(0)]],device const float* mean [[buffer(1)]],
    device const float* mean_correlation [[buffer(2)]],device float* coefficient_a [[buffer(3)]],device float* coefficient_b [[buffer(4)]],
    constant GuidedFilterUniforms& u [[buffer(5)]],uint gid [[thread_position_in_grid]]){
  if(gid>=u.pixel_count)return;float variance=max(0.0f,mean_correlation[gid]-mean[gid]*mean[gid]);
  float a=variance/(variance+max(1.0e-8f,u.epsilon));coefficient_a[gid]=a;coefficient_b[gid]=mean[gid]*(1.0f-a);}
kernel void retained_guided_compose(device const float* input [[buffer(0)]],device const float* mean_a [[buffer(1)]],
    device const float* mean_b [[buffer(2)]],device float* output [[buffer(3)]],constant GuidedFilterUniforms& u [[buffer(4)]],
    uint gid [[thread_position_in_grid]]){if(gid>=u.pixel_count)return;output[gid]=max(0.0f,mean_a[gid]*input[gid]+mean_b[gid]);}
)"];
  }
};

struct MetalWorkingSurface::Impl final {
  id<MTLBuffer> pixel_buffer = nil;
  id<MTLCommandBuffer> producer_command_buffer = nil;
  id<MTLSharedEvent> ready_event = nil;
  RenderSurfaceDescriptor descriptor;
  std::uint64_t device_registry_id = 0U;
  std::uint64_t ready_event_value = 0U;
  std::uint64_t byte_size = 0U;
};

MetalWorkingSurface::MetalWorkingSurface(std::shared_ptr<Impl> impl)
    : impl_(std::move(impl)) {}
MetalWorkingSurface::~MetalWorkingSurface() = default;

std::string_view MetalWorkingSurface::backend_identity() const noexcept {
  return "metal-working-rgba32f";
}

std::uint64_t MetalWorkingSurface::byte_size() const noexcept {
  return impl_ != nullptr ? impl_->byte_size : 0U;
}

bool MetalWorkingSurface::valid_for(
    const RenderSurfaceDescriptor& descriptor) const noexcept {
  return impl_ != nullptr && impl_->pixel_buffer != nil &&
         impl_->producer_command_buffer != nil && impl_->ready_event != nil &&
         impl_->ready_event_value != 0U && impl_->descriptor == descriptor &&
         impl_->byte_size == static_cast<std::uint64_t>(descriptor.width) *
                                 static_cast<std::uint64_t>(descriptor.height) *
                                 sizeof(ColorPixel);
}

bool MetalWorkingSurface::copy_pixels(
    std::vector<ColorPixel>* destination,
    CancellationToken cancellation) const {
  if (destination == nullptr || cancellation.cancelled() || impl_ == nullptr ||
      !valid_for(impl_->descriptor)) {
    return false;
  }
  @autoreleasepool {
    [impl_->producer_command_buffer waitUntilCompleted];
    if (cancellation.cancelled() || !producer_completed_successfully()) {
      return false;
    }
    auto materialized = std::vector<ColorPixel>(
        static_cast<std::size_t>(impl_->descriptor.width) *
        static_cast<std::size_t>(impl_->descriptor.height));
    std::memcpy(
        materialized.data(), [impl_->pixel_buffer contents], impl_->byte_size);
    if (!std::ranges::all_of(materialized, [](const ColorPixel& pixel) {
          return std::isfinite(pixel.red) && std::isfinite(pixel.green) &&
                 std::isfinite(pixel.blue) && std::isfinite(pixel.alpha);
        })) {
      return false;
    }
    *destination = std::move(materialized);
  }
  return true;
}

bool MetalWorkingSurface::copy_pixels_validates_finite() const noexcept {
  return true;
}

bool MetalWorkingSurface::copy_sampled_pixels(
    int sampled_width, int sampled_height,
    std::vector<ColorPixel>* destination,
    CancellationToken cancellation) const {
  if (destination == nullptr || impl_ == nullptr || !valid_for(impl_->descriptor) ||
      sampled_width <= 0 || sampled_height <= 0 ||
      impl_->descriptor.width > static_cast<std::uint32_t>(std::numeric_limits<int>::max()) ||
      impl_->descriptor.height > static_cast<std::uint32_t>(std::numeric_limits<int>::max()) ||
      static_cast<std::uint32_t>(sampled_width) > impl_->descriptor.width ||
      static_cast<std::uint32_t>(sampled_height) > impl_->descriptor.height ||
      cancellation.cancelled()) return false;
  @autoreleasepool {
    [impl_->producer_command_buffer waitUntilCompleted];
    if (cancellation.cancelled() || !producer_completed_successfully()) return false;
    const auto* source = static_cast<const ColorPixel*>([impl_->pixel_buffer contents]);
    if (source == nullptr) return false;
    auto sampled = std::vector<ColorPixel>(
        static_cast<std::size_t>(sampled_width) * static_cast<std::size_t>(sampled_height));
    const auto width = static_cast<int>(impl_->descriptor.width);
    const auto height = static_cast<int>(impl_->descriptor.height);
    const auto x_scale = static_cast<double>(width) / sampled_width;
    const auto y_scale = static_cast<double>(height) / sampled_height;
    // Match the existing CPU histogram sampler exactly. This shared Metal buffer
    // is immutable after producer completion; only selected samples are copied.
    for (int y = 0; y < sampled_height; ++y) {
      if (cancellation.cancelled()) return false;
      const auto source_y = std::clamp(static_cast<int>((y + 0.5) * y_scale), 0, height - 1);
      for (int x = 0; x < sampled_width; ++x) {
        const auto source_x = std::clamp(static_cast<int>((x + 0.5) * x_scale), 0, width - 1);
        const auto pixel = source[static_cast<std::size_t>(source_y) * static_cast<std::size_t>(width) +
                                  static_cast<std::size_t>(source_x)];
        if (!std::isfinite(pixel.red) || !std::isfinite(pixel.green) ||
            !std::isfinite(pixel.blue) || !std::isfinite(pixel.alpha)) return false;
        sampled[static_cast<std::size_t>(y) * static_cast<std::size_t>(sampled_width) +
                static_cast<std::size_t>(x)] = pixel;
      }
    }
    if (cancellation.cancelled()) return false;
    *destination = std::move(sampled);
  }
  return true;
}

RenderSurfaceDescriptor MetalWorkingSurface::descriptor() const {
  return impl_ != nullptr ? impl_->descriptor : RenderSurfaceDescriptor{};
}

std::uintptr_t MetalWorkingSurface::native_buffer_handle() const {
  return impl_ != nullptr && impl_->pixel_buffer != nil
             ? reinterpret_cast<std::uintptr_t>(impl_->pixel_buffer)
             : 0U;
}

std::uint64_t MetalWorkingSurface::device_registry_id() const {
  return impl_ != nullptr ? impl_->device_registry_id : 0U;
}

std::uintptr_t MetalWorkingSurface::native_ready_event_handle() const {
  return impl_ != nullptr && impl_->ready_event != nil
             ? reinterpret_cast<std::uintptr_t>(impl_->ready_event)
             : 0U;
}

std::uint64_t MetalWorkingSurface::ready_event_value() const {
  return impl_ != nullptr ? impl_->ready_event_value : 0U;
}

bool MetalWorkingSurface::producer_completed_successfully() const {
  return impl_ != nullptr && impl_->producer_command_buffer != nil &&
         impl_->producer_command_buffer.status == MTLCommandBufferStatusCompleted;
}

struct MetalOutputSurface::Impl final {
  id<MTLTexture> texture = nil;
  id<MTLCommandBuffer> producer_command_buffer = nil;
  id<MTLSharedEvent> ready_event = nil;
  std::shared_ptr<const MetalWorkingSurface> upstream_surface;
  int width = 0;
  int height = 0;
  std::uint64_t device_registry_id = 0U;
  std::uint64_t ready_event_value = 0U;
  RenderSurfaceDescriptor descriptor;
};

MetalOutputSurface::MetalOutputSurface(std::shared_ptr<Impl> impl)
    : impl_(std::move(impl)) {}
MetalOutputSurface::~MetalOutputSurface() = default;

std::string_view MetalOutputSurface::backend_identity() const noexcept {
  return "metal-output-bgra8-srgb";
}

std::uint64_t MetalOutputSurface::byte_size() const noexcept {
  return static_cast<std::uint64_t>(std::max(width(), 0)) *
         static_cast<std::uint64_t>(std::max(height(), 0)) * 4U;
}

bool MetalOutputSurface::valid_for(
    const RenderSurfaceDescriptor& descriptor) const noexcept {
  return impl_ != nullptr && impl_->texture != nil &&
         impl_->producer_command_buffer != nil &&
         ((impl_->ready_event != nil && impl_->ready_event_value != 0U) ||
          impl_->producer_command_buffer.status == MTLCommandBufferStatusCompleted) &&
         descriptor.width > 0U &&
         descriptor.height > 0U &&
         descriptor.width == static_cast<std::uint32_t>(width()) &&
         descriptor.height == static_cast<std::uint32_t>(height()) &&
         descriptor == impl_->descriptor;
}

bool MetalOutputSurface::copy_pixels(
    std::vector<ColorPixel>* destination,
    CancellationToken cancellation) const {
  if (destination == nullptr || cancellation.cancelled() || impl_ == nullptr) {
    return false;
  }
  auto encoded = std::vector<std::uint8_t>(
      static_cast<std::size_t>(std::max(width(), 0)) *
      static_cast<std::size_t>(std::max(height(), 0)) * 4U);
  if (!copy_bgra8_pixels_for_testing(encoded) || cancellation.cancelled()) {
    return false;
  }
  auto materialized = std::vector<ColorPixel>(encoded.size() / 4U);
  constexpr auto kCodeScale = 1.0F / 255.0F;
  for (auto index = std::size_t{0}; index < materialized.size(); ++index) {
    const auto offset = index * 4U;
    materialized[index] = ColorPixel{
        .red = static_cast<float>(encoded[offset + 2U]) * kCodeScale,
        .green = static_cast<float>(encoded[offset + 1U]) * kCodeScale,
        .blue = static_cast<float>(encoded[offset]) * kCodeScale,
        .alpha = static_cast<float>(encoded[offset + 3U]) * kCodeScale,
    };
  }
  *destination = std::move(materialized);
  return true;
}

bool MetalOutputSurface::copy_pixels_validates_finite() const noexcept {
  // Output channels are decoded from finite 8-bit values.
  return true;
}

int MetalOutputSurface::width() const {
  return impl_ != nullptr ? impl_->width : 0;
}

int MetalOutputSurface::height() const {
  return impl_ != nullptr ? impl_->height : 0;
}

MetalOutputSurfaceFormat MetalOutputSurface::format() const {
  return MetalOutputSurfaceFormat::Bgra8UnormSrgbEncoded;
}

std::uintptr_t MetalOutputSurface::native_texture_handle() const {
  return impl_ != nullptr && impl_->texture != nil
             ? reinterpret_cast<std::uintptr_t>(impl_->texture)
             : 0U;
}

std::uint64_t MetalOutputSurface::device_registry_id() const {
  return impl_ != nullptr ? impl_->device_registry_id : 0U;
}

std::uintptr_t MetalOutputSurface::native_ready_event_handle() const {
  return impl_ != nullptr && impl_->ready_event != nil
             ? reinterpret_cast<std::uintptr_t>(impl_->ready_event)
             : 0U;
}

std::uint64_t MetalOutputSurface::ready_event_value() const {
  return impl_ != nullptr ? impl_->ready_event_value : 0U;
}

bool MetalOutputSurface::producer_completed_successfully() const {
  return impl_ != nullptr && impl_->producer_command_buffer != nil &&
         impl_->producer_command_buffer.status == MTLCommandBufferStatusCompleted &&
         (impl_->upstream_surface == nullptr ||
          impl_->upstream_surface->producer_completed_successfully());
}

bool MetalOutputSurface::copy_bgra8_pixels_for_testing(
    std::span<std::uint8_t> destination) const {
  return copy_bgra8_region(0, 0, width(), height(), destination);
}

bool MetalOutputSurface::copy_bgra8_region(
    int x, int y, int region_width, int region_height,
    std::span<std::uint8_t> destination,
    CancellationToken cancellation) const {
  if (cancellation.cancelled() || x < 0 || y < 0 || region_width <= 0 || region_height <= 0 ||
      x > width() || y > height() || region_width > width() - x || region_height > height() - y) {
    return false;
  }
  const auto required = static_cast<std::size_t>(region_width) *
                        static_cast<std::size_t>(region_height) * 4U;
  if (impl_ == nullptr || impl_->texture == nil ||
      destination.size() != required) {
    return false;
  }
  @autoreleasepool {
    [impl_->producer_command_buffer waitUntilCompleted];
    if (cancellation.cancelled() || !producer_completed_successfully()) {
      return false;
    }
    [impl_->texture getBytes:destination.data()
                 bytesPerRow:static_cast<NSUInteger>(region_width) * 4U
                  fromRegion:MTLRegionMake2D(
                                 static_cast<NSUInteger>(x),
                                 static_cast<NSUInteger>(y),
                                 static_cast<NSUInteger>(region_width),
                                 static_cast<NSUInteger>(region_height))
                 mipmapLevel:0];
  }
  return !cancellation.cancelled();
}

MetalPipelineBackend::MetalPipelineBackend() : impl_(std::make_unique<Impl>()) {}
MetalPipelineBackend::~MetalPipelineBackend() = default;

bool MetalPipelineBackend::available() const { return impl_ && impl_->is_available; }

std::string MetalPipelineBackend::unavailable_reason() const {
  if (!impl_) {
    return "backend_not_constructed";
  }
  return impl_->unavailable_reason;
}

std::string MetalPipelineBackend::device_name() const {
  if (!available() || impl_->device == nil || impl_->device.name == nil) {
    return {};
  }
  const auto* name = impl_->device.name.UTF8String;
  return name == nullptr ? std::string{} : std::string(name);
}

MetalColorLutCacheStats
MetalPipelineBackend::color_lut_cache_stats() const {
  if (!impl_) {
    return {};
  }
  const std::scoped_lock lock(
      impl_->color_lut_mutex);
  return MetalColorLutCacheStats{
      .entries =
          impl_->color_lut_buffers.size(),
      .bytes =
          impl_->color_lut_buffer_bytes,
      .maximum_entries =
          Impl::kMaximumColorLutBufferEntries,
      .maximum_bytes =
          Impl::kMaximumColorLutBufferBytes,
  };
}

MetalColorLutCacheStats
MetalPipelineBackend::tone_lut_cache_stats() const {
  if (!impl_) {
    return {};
  }
  const std::scoped_lock lock(impl_->color_lut_mutex);
  return MetalColorLutCacheStats{
      .entries = impl_->tone_lut_buffers.size(),
      .bytes = impl_->tone_lut_buffer_bytes,
      .maximum_entries = Impl::kMaximumToneLutBufferEntries,
      .maximum_bytes = Impl::kMaximumToneLutBufferBytes,
  };
}

MetalColorLutCacheStats
MetalPipelineBackend::curve_lut_cache_stats() const {
  if (!impl_) {
    return {};
  }
  const std::scoped_lock lock(impl_->color_lut_mutex);
  return MetalColorLutCacheStats{
      .entries = impl_->curve_lut_buffers.size(),
      .bytes = impl_->curve_lut_buffer_bytes,
      .maximum_entries = Impl::kMaximumCurveLutBufferEntries,
      .maximum_bytes = Impl::kMaximumCurveLutBufferBytes,
  };
}

bool MetalPipelineBackend::apply_aces2_output_lut_target(
    std::vector<ColorPixel>* pixels,
    int width,
    int height,
    const CompiledAces2OutputLutApplication& application,
    ColorAdjustmentTelemetry* telemetry) {
  const auto fail = [&](std::string reason) {
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason = std::move(reason);
    }
    return false;
  };
  if (!available()) {
    return fail(unavailable_reason());
  }
  if (pixels == nullptr || !application.ready() || width <= 0 || height <= 0) {
    return fail("invalid_aces2_output_lut_request");
  }
  const auto& lut = *application.lut;
  const auto pixel_count =
      static_cast<std::size_t>(width) * static_cast<std::size_t>(height);
  if (pixels->size() != pixel_count) {
    return fail("aces2_output_lut_pixel_count_mismatch");
  }
  const auto finite_inputs = std::all_of(
      pixels->begin(),
      pixels->end(),
      [](const ColorPixel& pixel) {
        return std::isfinite(pixel.red) && std::isfinite(pixel.green) &&
               std::isfinite(pixel.blue) && std::isfinite(pixel.alpha);
      });
  if (!finite_inputs) {
    return fail("aces2_output_source_non_finite");
  }
  const auto finite_parameters =
      std::isfinite(application.black_point_headroom) &&
      std::isfinite(application.display_headroom) &&
      std::isfinite(application.source_black_point) &&
      std::isfinite(application.output_black_point);
  if (!finite_parameters) {
    return fail("aces2_output_application_non_finite");
  }
  const auto stage_start = std::chrono::steady_clock::now();
  auto lut_upload_bytes = std::size_t{0U};

  @autoreleasepool {
    id<MTLBuffer> active_lut_buffer =
        impl_->aces2_output_lut_buffer(lut, &lut_upload_bytes);
    if (!active_lut_buffer) {
      return fail("aces2_output_lut_buffer_allocation_failed");
    }

    const auto pixel_buffer_size = pixel_count * sizeof(ColorPixel);
    id<MTLBuffer> pixel_buffer = [impl_->device
        newBufferWithLength:pixel_buffer_size
                    options:MTLResourceStorageModeShared];
    if (!pixel_buffer) {
      return fail("aces2_output_pixel_buffer_allocation_failed");
    }
    std::memcpy([pixel_buffer contents], pixels->data(), pixel_buffer_size);

    const auto uniforms =
        make_aces2_output_lut_uniforms(application, width, height);

    id<MTLCommandBuffer> command_buffer = [impl_->command_queue commandBuffer];
    id<MTLComputeCommandEncoder> encoder =
        [command_buffer computeCommandEncoder];
    if (!command_buffer || !encoder) {
      return fail("aces2_output_command_encoder_unavailable");
    }
    [encoder setComputePipelineState:impl_->aces2_output_lut_pipeline];
    [encoder setBuffer:pixel_buffer offset:0 atIndex:0];
    [encoder setBuffer:active_lut_buffer offset:0 atIndex:1];
    [encoder setBytes:&uniforms length:sizeof(uniforms) atIndex:2];
    auto thread_group_size =
        impl_->aces2_output_lut_pipeline.maxTotalThreadsPerThreadgroup;
    thread_group_size = std::min<NSUInteger>(thread_group_size, 256U);
    [encoder dispatchThreads:MTLSizeMake(pixel_count, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(thread_group_size, 1, 1)];
    [encoder endEncoding];
    [command_buffer commit];
    [command_buffer waitUntilCompleted];
    if (command_buffer.status != MTLCommandBufferStatusCompleted) {
      return fail("aces2_output_command_buffer_failed");
    }
    const auto* const output =
        static_cast<const ColorPixel*>([pixel_buffer contents]);
    for (std::size_t index = 0U; index < pixel_count; ++index) {
      const auto& pixel = output[index];
      const auto expected_alpha = std::clamp(
          static_cast<double>((*pixels)[index].alpha), 0.0, 1.0);
      if (!std::isfinite(pixel.red) || !std::isfinite(pixel.green) ||
          !std::isfinite(pixel.blue) || !std::isfinite(pixel.alpha) ||
          std::abs(static_cast<double>(pixel.alpha) - expected_alpha) >
              1.0e-6) {
        return fail("aces2_output_gpu_validation_failed");
      }
    }
    std::memcpy(pixels->data(), output, pixel_buffer_size);
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason.clear();
      telemetry->final_output_ms += std::chrono::duration_cast<
          std::chrono::milliseconds>(
          std::chrono::steady_clock::now() - stage_start)
                                        .count();
      telemetry->gpu_cpu_to_gpu_bytes += static_cast<std::int64_t>(
          pixel_buffer_size + lut_upload_bytes);
      telemetry->gpu_gpu_to_cpu_bytes +=
          static_cast<std::int64_t>(pixel_buffer_size);
      telemetry->gpu_command_buffer_count += 1;
      telemetry->gpu_kernel_dispatch_count += 1;
    }
    return true;
  }
}

std::shared_ptr<const MetalOutputSurface>
MetalPipelineBackend::publish_aces2_output_lut_srgb8_surface(
    std::span<const ColorPixel> pixels,
    int width,
    int height,
    const CompiledAces2OutputLutApplication& application,
    ColorAdjustmentTelemetry* telemetry,
    CancellationToken cancellation,
    bool defer_completion) {
  const auto fail = [&](std::string reason) {
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason = std::move(reason);
    }
    return std::shared_ptr<const MetalOutputSurface>{};
  };
  if (!available()) {
    return fail(unavailable_reason());
  }
  if (!application.ready() || width <= 0 || height <= 0 ||
      cancellation.cancelled()) {
    return fail(cancellation.cancelled()
                    ? "aces2_output_native_surface_cancelled"
                    : "invalid_aces2_output_native_surface_request");
  }
  const auto pixel_count =
      static_cast<std::size_t>(width) * static_cast<std::size_t>(height);
  if (pixels.size() != pixel_count) {
    return fail("aces2_output_native_surface_pixel_count_mismatch");
  }
  const auto finite_inputs = std::all_of(
      pixels.begin(), pixels.end(), [](const ColorPixel& pixel) {
        return std::isfinite(pixel.red) && std::isfinite(pixel.green) &&
               std::isfinite(pixel.blue) && std::isfinite(pixel.alpha);
      });
  const auto finite_parameters =
      std::isfinite(application.black_point_headroom) &&
      std::isfinite(application.display_headroom) &&
      std::isfinite(application.source_black_point) &&
      std::isfinite(application.output_black_point);
  if (!finite_inputs || !finite_parameters) {
    return fail("aces2_output_native_surface_non_finite");
  }

  const auto stage_start = std::chrono::steady_clock::now();
  auto lut_upload_bytes = std::size_t{0U};
  @autoreleasepool {
    id<MTLBuffer> lut_buffer = impl_->aces2_output_lut_buffer(
        *application.lut, &lut_upload_bytes);
    if (!lut_buffer) {
      return fail("aces2_output_native_lut_buffer_allocation_failed");
    }
    const auto pixel_buffer_size = pixel_count * sizeof(ColorPixel);
    id<MTLBuffer> pixel_buffer = [impl_->device
        newBufferWithLength:pixel_buffer_size
                    options:MTLResourceStorageModeShared];
    if (!pixel_buffer) {
      return fail("aces2_output_native_pixel_buffer_allocation_failed");
    }
    std::memcpy([pixel_buffer contents], pixels.data(), pixel_buffer_size);

    auto* descriptor = [MTLTextureDescriptor
        texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                     width:static_cast<NSUInteger>(width)
                                    height:static_cast<NSUInteger>(height)
                                 mipmapped:NO];
    descriptor.usage = MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
    descriptor.storageMode = MTLStorageModeShared;
    id<MTLTexture> texture = [impl_->device newTextureWithDescriptor:descriptor];
    if (!texture) {
      return fail("aces2_output_native_texture_allocation_failed");
    }

    const auto uniforms =
        make_aces2_output_lut_uniforms(application, width, height);
    id<MTLCommandBuffer> command_buffer = [impl_->command_queue commandBuffer];
    id<MTLComputeCommandEncoder> encoder =
        [command_buffer computeCommandEncoder];
    if (!command_buffer || !encoder) {
      return fail("aces2_output_native_command_encoder_unavailable");
    }
    [encoder setComputePipelineState:impl_->aces2_output_lut_srgb8_pipeline];
    [encoder setBuffer:pixel_buffer offset:0 atIndex:0];
    [encoder setBuffer:lut_buffer offset:0 atIndex:1];
    [encoder setBytes:&uniforms length:sizeof(uniforms) atIndex:2];
    [encoder setTexture:texture atIndex:0];
    const auto thread_width = std::max<NSUInteger>(
        1U, impl_->aces2_output_lut_srgb8_pipeline.threadExecutionWidth);
    const auto thread_height = std::max<NSUInteger>(
        1U,
        impl_->aces2_output_lut_srgb8_pipeline.maxTotalThreadsPerThreadgroup /
            thread_width);
    [encoder dispatchThreads:MTLSizeMake(
                                 static_cast<NSUInteger>(width),
                                 static_cast<NSUInteger>(height),
                                 1)
         threadsPerThreadgroup:MTLSizeMake(thread_width, thread_height, 1)];
    [encoder endEncoding];
    id<MTLSharedEvent> ready_event =
        defer_completion ? [impl_->device newSharedEvent] : nil;
    const auto completion_deferred = ready_event != nil;
    if (completion_deferred) {
      [command_buffer encodeSignalEvent:ready_event value:1U];
      [command_buffer addCompletedHandler:^(id<MTLCommandBuffer> completed) {
        if (completed.status != MTLCommandBufferStatusCompleted &&
            ready_event.signaledValue < 1U) {
          ready_event.signaledValue = 1U;
        }
      }];
    }
    if (cancellation.cancelled()) {
      return fail("aces2_output_native_surface_cancelled");
    }
    [command_buffer commit];
    if (!completion_deferred) {
      [command_buffer waitUntilCompleted];
      if (command_buffer.status != MTLCommandBufferStatusCompleted) {
        return fail("aces2_output_native_command_buffer_failed");
      }
      if (cancellation.cancelled()) {
        return fail("aces2_output_native_surface_cancelled");
      }
    }

    auto surface_impl = std::make_shared<MetalOutputSurface::Impl>();
    surface_impl->texture = texture;
    surface_impl->producer_command_buffer = command_buffer;
    surface_impl->ready_event = ready_event;
    surface_impl->width = width;
    surface_impl->height = height;
    surface_impl->device_registry_id =
        static_cast<std::uint64_t>(impl_->device.registryID);
    surface_impl->ready_event_value = completion_deferred ? 1U : 0U;
    surface_impl->descriptor = srgb8_output_descriptor(width, height);
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason.clear();
      telemetry->final_output_ms += std::chrono::duration_cast<
          std::chrono::milliseconds>(
          std::chrono::steady_clock::now() - stage_start)
                                        .count();
      telemetry->gpu_cpu_to_gpu_bytes += static_cast<std::int64_t>(
          pixel_buffer_size + lut_upload_bytes);
      telemetry->gpu_command_buffer_count += 1;
      telemetry->gpu_kernel_dispatch_count += 1;
    }
    return std::shared_ptr<const MetalOutputSurface>(
        new MetalOutputSurface(std::move(surface_impl)));
  }
}

std::shared_ptr<const MetalOutputSurface>
MetalPipelineBackend::publish_aces2_output_lut_srgb8_surface(
    const std::shared_ptr<const MetalWorkingSurface>& working_surface,
    const CompiledAces2OutputLutApplication& application,
    ColorAdjustmentTelemetry* telemetry,
    CancellationToken cancellation,
    bool defer_completion) {
  const auto descriptor = working_surface != nullptr
      ? working_surface->descriptor() : RenderSurfaceDescriptor{};
  return publish_aces2_output_lut_srgb8_surface(
      working_surface, 0, 0, static_cast<int>(descriptor.width),
      static_cast<int>(descriptor.height), application, telemetry,
      cancellation, defer_completion);
}

std::shared_ptr<const MetalOutputSurface>
MetalPipelineBackend::publish_aces2_output_lut_srgb8_surface(
    const std::shared_ptr<const MetalWorkingSurface>& working_surface,
    int source_x,
    int source_y,
    int width,
    int height,
    const CompiledAces2OutputLutApplication& application,
    ColorAdjustmentTelemetry* telemetry,
    CancellationToken cancellation,
    bool defer_completion) {
  const auto fail = [&](std::string reason) {
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason = std::move(reason);
    }
    return std::shared_ptr<const MetalOutputSurface>{};
  };
  if (!available()) {
    return fail(unavailable_reason());
  }
  if (working_surface == nullptr || !application.ready() ||
      cancellation.cancelled()) {
    return fail(cancellation.cancelled()
                    ? "aces2_output_native_surface_cancelled"
                    : "invalid_aces2_output_native_working_surface_request");
  }
  const auto source_descriptor = working_surface->descriptor();
  const auto source_width = static_cast<int>(source_descriptor.width);
  const auto source_height = static_cast<int>(source_descriptor.height);
  const auto finite_parameters =
      std::isfinite(application.black_point_headroom) &&
      std::isfinite(application.display_headroom) &&
      std::isfinite(application.source_black_point) &&
      std::isfinite(application.output_black_point);
  if (width <= 0 || height <= 0 || source_x < 0 || source_y < 0 ||
      source_x > source_width - width || source_y > source_height - height ||
      !finite_parameters ||
      !working_surface->valid_for(source_descriptor) ||
      working_surface->device_registry_id() !=
          static_cast<std::uint64_t>(impl_->device.registryID) ||
      working_surface->impl_->pixel_buffer == nil ||
      working_surface->impl_->ready_event == nil) {
    return fail("aces2_output_native_working_surface_invalid");
  }

  const auto stage_start = std::chrono::steady_clock::now();
  auto lut_upload_bytes = std::size_t{0U};
  @autoreleasepool {
    id<MTLBuffer> lut_buffer = impl_->aces2_output_lut_buffer(
        *application.lut, &lut_upload_bytes);
    if (lut_buffer == nil) {
      return fail("aces2_output_native_lut_buffer_allocation_failed");
    }
    auto* texture_descriptor = [MTLTextureDescriptor
        texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                     width:static_cast<NSUInteger>(width)
                                    height:static_cast<NSUInteger>(height)
                                 mipmapped:NO];
    texture_descriptor.usage =
        MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
    texture_descriptor.storageMode = MTLStorageModeShared;
    id<MTLTexture> texture =
        [impl_->device newTextureWithDescriptor:texture_descriptor];
    if (texture == nil) {
      return fail("aces2_output_native_texture_allocation_failed");
    }

    const auto uniforms = make_aces2_output_lut_uniforms(
        application, width, height, source_width, source_x, source_y);
    id<MTLCommandBuffer> command_buffer = [impl_->command_queue commandBuffer];
    if (command_buffer == nil) {
      return fail("aces2_output_native_command_encoder_unavailable");
    }
    [command_buffer encodeWaitForEvent:working_surface->impl_->ready_event
                                 value:working_surface->impl_->ready_event_value];
    id<MTLComputeCommandEncoder> encoder =
        [command_buffer computeCommandEncoder];
    if (encoder == nil) {
      return fail("aces2_output_native_command_encoder_unavailable");
    }
    [encoder setComputePipelineState:impl_->aces2_output_lut_srgb8_pipeline];
    [encoder setBuffer:working_surface->impl_->pixel_buffer offset:0 atIndex:0];
    [encoder setBuffer:lut_buffer offset:0 atIndex:1];
    [encoder setBytes:&uniforms length:sizeof(uniforms) atIndex:2];
    [encoder setTexture:texture atIndex:0];
    const auto thread_width = std::max<NSUInteger>(
        1U, impl_->aces2_output_lut_srgb8_pipeline.threadExecutionWidth);
    const auto thread_height = std::max<NSUInteger>(
        1U,
        impl_->aces2_output_lut_srgb8_pipeline.maxTotalThreadsPerThreadgroup /
            thread_width);
    [encoder dispatchThreads:MTLSizeMake(
                                 static_cast<NSUInteger>(width),
                                 static_cast<NSUInteger>(height),
                                 1)
         threadsPerThreadgroup:MTLSizeMake(thread_width, thread_height, 1)];
    [encoder endEncoding];
    id<MTLSharedEvent> ready_event =
        defer_completion ? [impl_->device newSharedEvent] : nil;
    const auto completion_deferred = ready_event != nil;
    if (completion_deferred) {
      [command_buffer encodeSignalEvent:ready_event value:1U];
      [command_buffer addCompletedHandler:^(id<MTLCommandBuffer> completed) {
        if (completed.status != MTLCommandBufferStatusCompleted &&
            ready_event.signaledValue < 1U) {
          ready_event.signaledValue = 1U;
        }
      }];
    }
    if (cancellation.cancelled()) {
      return fail("aces2_output_native_surface_cancelled");
    }
    [command_buffer commit];
    if (!completion_deferred) {
      [command_buffer waitUntilCompleted];
      if (command_buffer.status != MTLCommandBufferStatusCompleted ||
          !working_surface->producer_completed_successfully()) {
        return fail("aces2_output_native_command_buffer_failed");
      }
      if (cancellation.cancelled()) {
        return fail("aces2_output_native_surface_cancelled");
      }
    }

    auto surface_impl = std::make_shared<MetalOutputSurface::Impl>();
    surface_impl->texture = texture;
    surface_impl->producer_command_buffer = command_buffer;
    surface_impl->ready_event = ready_event;
    surface_impl->upstream_surface = working_surface;
    surface_impl->width = width;
    surface_impl->height = height;
    surface_impl->device_registry_id =
        static_cast<std::uint64_t>(impl_->device.registryID);
    surface_impl->ready_event_value = completion_deferred ? 1U : 0U;
    surface_impl->descriptor = srgb8_output_descriptor(width, height);
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason.clear();
      telemetry->final_output_ms += std::chrono::duration_cast<
          std::chrono::milliseconds>(
          std::chrono::steady_clock::now() - stage_start)
                                        .count();
      telemetry->gpu_cpu_to_gpu_bytes +=
          static_cast<std::int64_t>(lut_upload_bytes);
      telemetry->gpu_command_buffer_count += 1;
      telemetry->gpu_kernel_dispatch_count += 1;
    }
    return std::shared_ptr<const MetalOutputSurface>(
        new MetalOutputSurface(std::move(surface_impl)));
  }
}

std::shared_ptr<const MetalOutputSurface>
MetalPipelineBackend::publish_aces2_output_lut_icc_bgra8_surface(
    const std::shared_ptr<const MetalWorkingSurface>& working_surface,
    const CompiledAces2OutputLutApplication& application,
    const IccTransformLut3D& device_lut,
    const CompiledIccTransform& exact_device_transform,
    const RenderSurfaceDescriptor& publish_output,
    ColorAdjustmentTelemetry* telemetry,
    CancellationToken cancellation,
    bool defer_completion) {
  const auto fail = [&](std::string reason) {
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason = std::move(reason);
    }
    return std::shared_ptr<const MetalOutputSurface>{};
  };
  if (!available()) {
    return fail(unavailable_reason());
  }
  if (working_surface == nullptr || !application.ready() || !device_lut.valid() ||
      !exact_device_transform.ready() ||
      device_lut.transform_cache_key !=
          exact_device_transform.description().cache_key || cancellation.cancelled()) {
    return fail(cancellation.cancelled()
                    ? "aces2_icc_native_surface_cancelled"
                    : "invalid_aces2_icc_native_surface_request");
  }
  const auto source_descriptor = working_surface->descriptor();
  const auto width = static_cast<int>(source_descriptor.width);
  const auto height = static_cast<int>(source_descriptor.height);
  const auto finite_parameters =
      std::isfinite(application.black_point_headroom) &&
      std::isfinite(application.display_headroom) &&
      std::isfinite(application.source_black_point) &&
      std::isfinite(application.output_black_point);
  if (width <= 0 || height <= 0 || !finite_parameters ||
      application.display_headroom > 1.0 + 1.0e-9 ||
      !working_surface->valid_for(source_descriptor) ||
      working_surface->device_registry_id() !=
          static_cast<std::uint64_t>(impl_->device.registryID) ||
      working_surface->impl_->pixel_buffer == nil ||
      working_surface->impl_->ready_event == nil ||
      publish_output.pixel_encoding != RenderPixelEncoding::DisplayEncodedFloat ||
      publish_output.color_domain != RenderColorDomain::Device ||
      publish_output.range != RenderRangeModel::DisplayBounded ||
      publish_output.alpha != RenderAlphaModel::Straight ||
      publish_output.color_space_identity.empty() ||
      publish_output.transfer_identity.empty() ||
      publish_output.width != source_descriptor.width ||
      publish_output.height != source_descriptor.height) {
    return fail("aces2_icc_native_surface_contract_invalid");
  }

  const auto stage_start = std::chrono::steady_clock::now();
  auto output_lut_upload_bytes = std::size_t{0U};
  auto icc_lut_upload_bytes = std::size_t{0U};
  @autoreleasepool {
    id<MTLBuffer> output_lut_buffer = impl_->aces2_output_lut_buffer(
        *application.lut, &output_lut_upload_bytes);
    if (output_lut_buffer == nil) {
      return fail("aces2_icc_native_output_lut_allocation_failed");
    }

    id<MTLBuffer> icc_table_buffer = nil;
    id<MTLBuffer> icc_unsafe_cells_buffer = nil;
    {
      const std::scoped_lock lock(impl_->icc_transform_lut_mutex);
      const auto cached = std::find_if(
          impl_->icc_transform_lut_buffers.begin(),
          impl_->icc_transform_lut_buffers.end(),
          [&](const Impl::IccTransformLutBufferEntry& entry) {
            return entry.key == device_lut.cache_key;
          });
      if (cached != impl_->icc_transform_lut_buffers.end()) {
        cached->last_use = ++impl_->icc_transform_lut_use_counter;
        icc_table_buffer = cached->table_buffer;
        icc_unsafe_cells_buffer = cached->unsafe_cells_buffer;
      } else {
        const auto table_bytes = device_lut.table.size() * sizeof(IccRgbaFloat);
        const auto unsafe_bytes =
            device_lut.unsafe_cells.size() * sizeof(std::uint8_t);
        id<MTLBuffer> uploaded_table = [impl_->device
            newBufferWithLength:table_bytes
                        options:MTLResourceStorageModeShared];
        id<MTLBuffer> uploaded_unsafe = [impl_->device
            newBufferWithLength:unsafe_bytes
                        options:MTLResourceStorageModeShared];
        if (uploaded_table == nil || uploaded_unsafe == nil) {
          return fail("aces2_icc_native_device_lut_allocation_failed");
        }
        std::memcpy([uploaded_table contents], device_lut.table.data(), table_bytes);
        std::memcpy(
            [uploaded_unsafe contents],
            device_lut.unsafe_cells.data(),
            unsafe_bytes);
        if (impl_->icc_transform_lut_buffers.size() >= 2U) {
          const auto least_recently_used = std::min_element(
              impl_->icc_transform_lut_buffers.begin(),
              impl_->icc_transform_lut_buffers.end(),
              [](const Impl::IccTransformLutBufferEntry& left,
                 const Impl::IccTransformLutBufferEntry& right) {
                return left.last_use < right.last_use;
              });
          impl_->icc_transform_lut_buffers.erase(least_recently_used);
        }
        impl_->icc_transform_lut_buffers.push_back({
            .key = device_lut.cache_key,
            .table_buffer = uploaded_table,
            .unsafe_cells_buffer = uploaded_unsafe,
            .last_use = ++impl_->icc_transform_lut_use_counter,
        });
        icc_table_buffer = uploaded_table;
        icc_unsafe_cells_buffer = uploaded_unsafe;
        icc_lut_upload_bytes = table_bytes + unsafe_bytes;
      }
    }
    if (icc_table_buffer == nil || icc_unsafe_cells_buffer == nil) {
      return fail("aces2_icc_native_device_lut_unavailable");
    }

    const auto pixel_count = static_cast<std::size_t>(width) *
                             static_cast<std::size_t>(height);
    const auto pixel_buffer_size = pixel_count * sizeof(ColorPixel);
    id<MTLBuffer> target_buffer = [impl_->device
        newBufferWithLength:pixel_buffer_size
                    options:MTLResourceStorageModePrivate];
    if (target_buffer == nil) {
      return fail("aces2_icc_native_target_buffer_allocation_failed");
    }
    auto* texture_descriptor = [MTLTextureDescriptor
        texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm
                                     width:static_cast<NSUInteger>(width)
                                    height:static_cast<NSUInteger>(height)
                                 mipmapped:NO];
    texture_descriptor.usage =
        MTLTextureUsageShaderRead | MTLTextureUsageShaderWrite;
    texture_descriptor.storageMode = MTLStorageModeShared;
    id<MTLTexture> texture =
        [impl_->device newTextureWithDescriptor:texture_descriptor];
    if (texture == nil) {
      return fail("aces2_icc_native_texture_allocation_failed");
    }

    const auto output_uniforms =
        make_aces2_output_lut_uniforms(application, width, height);
    const auto icc_uniforms = IccTransformLutUniforms{
        .input_shaper_exponent =
            static_cast<float>(device_lut.settings.input_shaper_exponent),
        .lut_size = device_lut.settings.cube_size,
        .width = width,
        .height = height,
    };
    if (pixel_count > std::numeric_limits<std::uint32_t>::max()) {
      return fail("aces2_icc_native_pixel_count_exceeds_uint32");
    }
    id<MTLBuffer> exact_count_buffer = [impl_->device
        newBufferWithLength:sizeof(std::uint32_t)
                    options:MTLResourceStorageModeShared];
    if (exact_count_buffer == nil) {
      return fail("aces2_icc_native_exact_count_allocation_failed");
    }
    *static_cast<std::uint32_t*>([exact_count_buffer contents]) = 0U;

    id<MTLCommandBuffer> initial_command_buffer =
        [impl_->command_queue commandBuffer];
    if (initial_command_buffer == nil) {
      return fail("aces2_icc_native_command_buffer_unavailable");
    }
    [initial_command_buffer encodeWaitForEvent:working_surface->impl_->ready_event
                                         value:working_surface->impl_->ready_event_value];
    id<MTLComputeCommandEncoder> output_encoder =
        [initial_command_buffer computeCommandEncoder];
    if (output_encoder == nil) {
      return fail("aces2_icc_native_output_encoder_unavailable");
    }
    [output_encoder
        setComputePipelineState:impl_->aces2_output_lut_target_pipeline];
    [output_encoder setBuffer:working_surface->impl_->pixel_buffer
                       offset:0
                      atIndex:0];
    [output_encoder setBuffer:target_buffer offset:0 atIndex:1];
    [output_encoder setBuffer:output_lut_buffer offset:0 atIndex:2];
    [output_encoder setBytes:&output_uniforms
                      length:sizeof(output_uniforms)
                     atIndex:3];
    auto output_thread_group_size =
        impl_->aces2_output_lut_target_pipeline.maxTotalThreadsPerThreadgroup;
    output_thread_group_size =
        std::min<NSUInteger>(output_thread_group_size, 256U);
    [output_encoder dispatchThreads:MTLSizeMake(pixel_count, 1, 1)
              threadsPerThreadgroup:MTLSizeMake(output_thread_group_size, 1, 1)];
    [output_encoder endEncoding];

    id<MTLComputeCommandEncoder> count_encoder =
        [initial_command_buffer computeCommandEncoder];
    if (count_encoder == nil) {
      return fail("aces2_icc_native_exact_count_encoder_unavailable");
    }
    [count_encoder setComputePipelineState:impl_->icc_exact_count_pipeline];
    [count_encoder setBuffer:target_buffer offset:0 atIndex:0];
    [count_encoder setBuffer:icc_unsafe_cells_buffer offset:0 atIndex:1];
    [count_encoder setBytes:&icc_uniforms length:sizeof(icc_uniforms) atIndex:2];
    [count_encoder setBuffer:exact_count_buffer offset:0 atIndex:3];
    auto count_thread_group_size =
        impl_->icc_exact_count_pipeline.maxTotalThreadsPerThreadgroup;
    count_thread_group_size =
        std::min<NSUInteger>(count_thread_group_size, 256U);
    [count_encoder dispatchThreads:MTLSizeMake(pixel_count, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(count_thread_group_size, 1, 1)];
    [count_encoder endEncoding];

    id<MTLComputeCommandEncoder> device_encoder =
        [initial_command_buffer computeCommandEncoder];
    if (device_encoder == nil) {
      return fail("aces2_icc_native_device_encoder_unavailable");
    }
    [device_encoder setComputePipelineState:impl_->icc_transform_lut_bgra8_pipeline];
    [device_encoder setBuffer:target_buffer offset:0 atIndex:0];
    [device_encoder setBuffer:icc_table_buffer offset:0 atIndex:1];
    [device_encoder setBytes:&icc_uniforms length:sizeof(icc_uniforms) atIndex:2];
    [device_encoder setTexture:texture atIndex:0];
    const auto device_thread_width = std::max<NSUInteger>(
        1U, impl_->icc_transform_lut_bgra8_pipeline.threadExecutionWidth);
    const auto device_thread_height = std::max<NSUInteger>(
        1U,
        impl_->icc_transform_lut_bgra8_pipeline.maxTotalThreadsPerThreadgroup /
            device_thread_width);
    [device_encoder dispatchThreads:MTLSizeMake(
                                        static_cast<NSUInteger>(width),
                                        static_cast<NSUInteger>(height),
                                        1)
              threadsPerThreadgroup:MTLSizeMake(
                                        device_thread_width,
                                        device_thread_height,
                                        1)];
    [device_encoder endEncoding];
    if (cancellation.cancelled()) {
      return fail("aces2_icc_native_surface_cancelled");
    }
    [initial_command_buffer commit];
    [initial_command_buffer waitUntilCompleted];
    if (initial_command_buffer.status != MTLCommandBufferStatusCompleted ||
        !working_surface->producer_completed_successfully()) {
      return fail("aces2_icc_native_initial_command_buffer_failed");
    }
    if (cancellation.cancelled()) {
      return fail("aces2_icc_native_surface_cancelled");
    }

    const auto exact_count = static_cast<std::size_t>(
        *static_cast<const std::uint32_t*>([exact_count_buffer contents]));
    constexpr auto kMaximumExactSubsetPixels = std::size_t{1'048'576U};
    const auto maximum_exact_subset = std::min(
        kMaximumExactSubsetPixels,
        std::max(std::size_t{1U}, pixel_count / 4U));
    if (exact_count > maximum_exact_subset) {
      if (telemetry != nullptr) {
        telemetry->gpu_cpu_to_gpu_bytes += static_cast<std::int64_t>(
            output_lut_upload_bytes + icc_lut_upload_bytes +
            sizeof(std::uint32_t));
        telemetry->gpu_gpu_to_cpu_bytes += sizeof(std::uint32_t);
        telemetry->gpu_command_buffer_count += 1;
        telemetry->gpu_kernel_dispatch_count += 3;
      }
      return fail("aces2_icc_native_exact_subset_exceeds_budget");
    }

    id<MTLCommandBuffer> producer_command_buffer = initial_command_buffer;
    id<MTLSharedEvent> ready_event = nil;
    auto completion_deferred = false;
    auto command_buffer_count = std::int64_t{1};
    auto kernel_dispatch_count = std::int64_t{3};
    auto cpu_to_gpu_bytes = output_lut_upload_bytes + icc_lut_upload_bytes +
                            sizeof(std::uint32_t);
    auto gpu_to_cpu_bytes = sizeof(std::uint32_t);
    if (exact_count > 0U) {
      const auto exact_pixel_bytes = exact_count * sizeof(IccRgbaFloat);
      const auto exact_index_bytes = exact_count * sizeof(std::uint32_t);
      id<MTLBuffer> exact_pixels_buffer = [impl_->device
          newBufferWithLength:exact_pixel_bytes
                      options:MTLResourceStorageModeShared];
      id<MTLBuffer> exact_indices_buffer = [impl_->device
          newBufferWithLength:exact_index_bytes
                      options:MTLResourceStorageModeShared];
      if (exact_pixels_buffer == nil || exact_indices_buffer == nil) {
        return fail("aces2_icc_native_exact_subset_allocation_failed");
      }
      *static_cast<std::uint32_t*>([exact_count_buffer contents]) = 0U;
      id<MTLCommandBuffer> compact_command_buffer =
          [impl_->command_queue commandBuffer];
      id<MTLComputeCommandEncoder> compact_encoder =
          [compact_command_buffer computeCommandEncoder];
      if (compact_command_buffer == nil || compact_encoder == nil) {
        return fail("aces2_icc_native_exact_compact_encoder_unavailable");
      }
      [compact_encoder setComputePipelineState:impl_->icc_exact_compact_pipeline];
      [compact_encoder setBuffer:target_buffer offset:0 atIndex:0];
      [compact_encoder setBuffer:icc_unsafe_cells_buffer offset:0 atIndex:1];
      [compact_encoder setBytes:&icc_uniforms length:sizeof(icc_uniforms) atIndex:2];
      [compact_encoder setBuffer:exact_count_buffer offset:0 atIndex:3];
      [compact_encoder setBuffer:exact_pixels_buffer offset:0 atIndex:4];
      [compact_encoder setBuffer:exact_indices_buffer offset:0 atIndex:5];
      auto compact_thread_group_size =
          impl_->icc_exact_compact_pipeline.maxTotalThreadsPerThreadgroup;
      compact_thread_group_size =
          std::min<NSUInteger>(compact_thread_group_size, 256U);
      [compact_encoder dispatchThreads:MTLSizeMake(pixel_count, 1, 1)
               threadsPerThreadgroup:MTLSizeMake(
                                         compact_thread_group_size, 1, 1)];
      [compact_encoder endEncoding];
      [compact_command_buffer commit];
      [compact_command_buffer waitUntilCompleted];
      if (compact_command_buffer.status != MTLCommandBufferStatusCompleted ||
          cancellation.cancelled() ||
          static_cast<std::size_t>(*static_cast<const std::uint32_t*>(
              [exact_count_buffer contents])) != exact_count) {
        return fail(cancellation.cancelled()
                        ? "aces2_icc_native_surface_cancelled"
                        : "aces2_icc_native_exact_compaction_failed");
      }

      auto exact_pixels = std::vector<IccRgbaFloat>(exact_count);
      std::memcpy(
          exact_pixels.data(), [exact_pixels_buffer contents], exact_pixel_bytes);
      const auto source_alpha = [&]() {
        auto values = std::vector<float>{};
        values.reserve(exact_count);
        for (const auto& pixel : exact_pixels) {
          values.push_back(pixel.alpha);
        }
        return values;
      }();
      if (!exact_device_transform.apply(exact_pixels) || cancellation.cancelled()) {
        return fail(cancellation.cancelled()
                        ? "aces2_icc_native_surface_cancelled"
                        : "aces2_icc_native_exact_transform_failed");
      }
      for (auto index = std::size_t{0U}; index < exact_pixels.size(); ++index) {
        const auto& pixel = exact_pixels[index];
        if (!std::isfinite(pixel.red) || !std::isfinite(pixel.green) ||
            !std::isfinite(pixel.blue) || !std::isfinite(pixel.alpha) ||
            pixel.alpha != source_alpha[index]) {
          return fail("aces2_icc_native_exact_transform_output_invalid");
        }
      }
      std::memcpy(
          [exact_pixels_buffer contents], exact_pixels.data(), exact_pixel_bytes);

      id<MTLCommandBuffer> patch_command_buffer =
          [impl_->command_queue commandBuffer];
      id<MTLComputeCommandEncoder> patch_encoder =
          [patch_command_buffer computeCommandEncoder];
      if (patch_command_buffer == nil || patch_encoder == nil) {
        return fail("aces2_icc_native_exact_patch_encoder_unavailable");
      }
      const auto exact_count_u32 = static_cast<std::uint32_t>(exact_count);
      const auto width_u32 = static_cast<std::uint32_t>(width);
      [patch_encoder setComputePipelineState:impl_->icc_exact_patch_bgra8_pipeline];
      [patch_encoder setBuffer:exact_pixels_buffer offset:0 atIndex:0];
      [patch_encoder setBuffer:exact_indices_buffer offset:0 atIndex:1];
      [patch_encoder setBytes:&exact_count_u32
                       length:sizeof(exact_count_u32)
                      atIndex:2];
      [patch_encoder setBytes:&width_u32 length:sizeof(width_u32) atIndex:3];
      [patch_encoder setTexture:texture atIndex:0];
      auto patch_thread_group_size =
          impl_->icc_exact_patch_bgra8_pipeline.maxTotalThreadsPerThreadgroup;
      patch_thread_group_size =
          std::min<NSUInteger>(patch_thread_group_size, 256U);
      [patch_encoder dispatchThreads:MTLSizeMake(exact_count, 1, 1)
             threadsPerThreadgroup:MTLSizeMake(patch_thread_group_size, 1, 1)];
      [patch_encoder endEncoding];
      ready_event = defer_completion ? [impl_->device newSharedEvent] : nil;
      completion_deferred = ready_event != nil;
      if (completion_deferred) {
        [patch_command_buffer encodeSignalEvent:ready_event value:1U];
        [patch_command_buffer addCompletedHandler:^(id<MTLCommandBuffer> completed) {
          if (completed.status != MTLCommandBufferStatusCompleted &&
              ready_event.signaledValue < 1U) {
            ready_event.signaledValue = 1U;
          }
        }];
      }
      [patch_command_buffer commit];
      if (!completion_deferred) {
        [patch_command_buffer waitUntilCompleted];
        if (patch_command_buffer.status != MTLCommandBufferStatusCompleted) {
          return fail("aces2_icc_native_exact_patch_failed");
        }
      }
      producer_command_buffer = patch_command_buffer;
      command_buffer_count += 2;
      kernel_dispatch_count += 2;
      cpu_to_gpu_bytes += sizeof(std::uint32_t) + exact_pixel_bytes;
      gpu_to_cpu_bytes += sizeof(std::uint32_t) + exact_pixel_bytes +
                          exact_index_bytes;
    }

    auto surface_impl = std::make_shared<MetalOutputSurface::Impl>();
    surface_impl->texture = texture;
    surface_impl->producer_command_buffer = producer_command_buffer;
    surface_impl->ready_event = ready_event;
    surface_impl->upstream_surface = working_surface;
    surface_impl->width = width;
    surface_impl->height = height;
    surface_impl->device_registry_id =
        static_cast<std::uint64_t>(impl_->device.registryID);
    surface_impl->ready_event_value = completion_deferred ? 1U : 0U;
    surface_impl->descriptor = publish_output;
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason.clear();
      telemetry->final_output_ms += std::chrono::duration_cast<
          std::chrono::milliseconds>(
          std::chrono::steady_clock::now() - stage_start)
                                        .count();
      telemetry->gpu_cpu_to_gpu_bytes +=
          static_cast<std::int64_t>(cpu_to_gpu_bytes);
      telemetry->gpu_gpu_to_cpu_bytes +=
          static_cast<std::int64_t>(gpu_to_cpu_bytes);
      telemetry->gpu_command_buffer_count += command_buffer_count;
      telemetry->gpu_kernel_dispatch_count += kernel_dispatch_count;
    }
    return std::shared_ptr<const MetalOutputSurface>(
        new MetalOutputSurface(std::move(surface_impl)));
  }
}

bool MetalPipelineBackend::apply_icc_transform_lut(
    std::span<IccRgbaFloat> pixels,
    int width,
    int height,
    const IccTransformLut3D& lut,
    const CompiledIccTransform& exact_transform,
    IccTransformLutApplyStats* apply_stats,
    ColorAdjustmentTelemetry* telemetry) {
  if (apply_stats != nullptr) {
    *apply_stats = {};
  }
  if (!available() || width <= 0 || height <= 0 ||
      !lut.valid() || !exact_transform.ready() ||
      lut.transform_cache_key != exact_transform.description().cache_key) {
    return false;
  }
  const auto pixel_count =
      static_cast<std::size_t>(width) * static_cast<std::size_t>(height);
  if (pixels.size() != pixel_count) {
    return false;
  }
  const auto finite_inputs = std::all_of(
      pixels.begin(),
      pixels.end(),
      [](const IccRgbaFloat& pixel) {
        return std::isfinite(pixel.red) && std::isfinite(pixel.green) &&
               std::isfinite(pixel.blue) && std::isfinite(pixel.alpha);
      });
  if (!finite_inputs) {
    return false;
  }

  std::vector<IccRgbaFloat> exact_pixels;
  std::vector<std::size_t> exact_indices;
  exact_pixels.reserve(pixel_count / 16U + 1U);
  exact_indices.reserve(exact_pixels.capacity());
  for (std::size_t index = 0U; index < pixel_count; ++index) {
    const auto& pixel = pixels[index];
    if (icc_lut_pixel_safe(
            lut,
            ColorPixel{
                .red = pixel.red,
                .green = pixel.green,
                .blue = pixel.blue,
                .alpha = pixel.alpha,
            })) {
      continue;
    }
    exact_pixels.push_back({
        .red = pixel.red,
        .green = pixel.green,
        .blue = pixel.blue,
        .alpha = pixel.alpha,
    });
    exact_indices.push_back(index);
  }
  if (!exact_pixels.empty() && !exact_transform.apply(exact_pixels)) {
    return false;
  }
  for (std::size_t index = 0U; index < exact_pixels.size(); ++index) {
    const auto& transformed = exact_pixels[index];
    const auto source_index = exact_indices[index];
    if (!std::isfinite(transformed.red) || !std::isfinite(transformed.green) ||
        !std::isfinite(transformed.blue) ||
        !std::isfinite(transformed.alpha) ||
        transformed.alpha != pixels[source_index].alpha) {
      return false;
    }
  }

  const auto stage_start = std::chrono::steady_clock::now();
  auto resource_upload_bytes = std::size_t{0U};
  const std::scoped_lock lock(impl_->icc_transform_lut_mutex);
  @autoreleasepool {
    id<MTLBuffer> table_buffer = nil;
    id<MTLBuffer> unsafe_cells_buffer = nil;
    const auto cached = std::find_if(
        impl_->icc_transform_lut_buffers.begin(),
        impl_->icc_transform_lut_buffers.end(),
        [&](const Impl::IccTransformLutBufferEntry& entry) {
          return entry.key == lut.cache_key;
        });
    if (cached != impl_->icc_transform_lut_buffers.end()) {
      cached->last_use = ++impl_->icc_transform_lut_use_counter;
      table_buffer = cached->table_buffer;
      unsafe_cells_buffer = cached->unsafe_cells_buffer;
    } else {
      const auto table_bytes = lut.table.size() * sizeof(IccRgbaFloat);
      const auto unsafe_bytes =
          lut.unsafe_cells.size() * sizeof(std::uint8_t);
      id<MTLBuffer> uploaded_table = [impl_->device
          newBufferWithLength:table_bytes
                      options:MTLResourceStorageModeShared];
      id<MTLBuffer> uploaded_unsafe_cells = [impl_->device
          newBufferWithLength:unsafe_bytes
                      options:MTLResourceStorageModeShared];
      if (!uploaded_table || !uploaded_unsafe_cells) {
        return false;
      }
      std::memcpy([uploaded_table contents], lut.table.data(), table_bytes);
      std::memcpy(
          [uploaded_unsafe_cells contents],
          lut.unsafe_cells.data(),
          unsafe_bytes);
      if (impl_->icc_transform_lut_buffers.size() >= 2U) {
        const auto least_recently_used = std::min_element(
            impl_->icc_transform_lut_buffers.begin(),
            impl_->icc_transform_lut_buffers.end(),
            [](const Impl::IccTransformLutBufferEntry& left,
               const Impl::IccTransformLutBufferEntry& right) {
              return left.last_use < right.last_use;
            });
        impl_->icc_transform_lut_buffers.erase(least_recently_used);
      }
      impl_->icc_transform_lut_buffers.push_back({
          .key = lut.cache_key,
          .table_buffer = uploaded_table,
          .unsafe_cells_buffer = uploaded_unsafe_cells,
          .last_use = ++impl_->icc_transform_lut_use_counter,
      });
      table_buffer = uploaded_table;
      unsafe_cells_buffer = uploaded_unsafe_cells;
      resource_upload_bytes = table_bytes + unsafe_bytes;
    }

    const auto pixel_buffer_size = pixel_count * sizeof(IccRgbaFloat);
    id<MTLBuffer> pixel_buffer = [impl_->device
        newBufferWithLength:pixel_buffer_size
                    options:MTLResourceStorageModeShared];
    if (!pixel_buffer) {
      return false;
    }
    std::memcpy([pixel_buffer contents], pixels.data(), pixel_buffer_size);
    const auto uniforms = IccTransformLutUniforms{
        .input_shaper_exponent =
            static_cast<float>(lut.settings.input_shaper_exponent),
        .lut_size = lut.settings.cube_size,
        .width = width,
        .height = height,
    };
    id<MTLCommandBuffer> command_buffer = [impl_->command_queue commandBuffer];
    id<MTLComputeCommandEncoder> encoder =
        [command_buffer computeCommandEncoder];
    if (!command_buffer || !encoder) {
      return false;
    }
    [encoder setComputePipelineState:impl_->icc_transform_lut_pipeline];
    [encoder setBuffer:pixel_buffer offset:0 atIndex:0];
    [encoder setBuffer:table_buffer offset:0 atIndex:1];
    [encoder setBuffer:unsafe_cells_buffer offset:0 atIndex:2];
    [encoder setBytes:&uniforms length:sizeof(uniforms) atIndex:3];
    auto thread_group_size =
        impl_->icc_transform_lut_pipeline.maxTotalThreadsPerThreadgroup;
    thread_group_size = std::min<NSUInteger>(thread_group_size, 256U);
    [encoder dispatchThreads:MTLSizeMake(pixel_count, 1, 1)
         threadsPerThreadgroup:MTLSizeMake(thread_group_size, 1, 1)];
    [encoder endEncoding];
    [command_buffer commit];
    [command_buffer waitUntilCompleted];
    if (command_buffer.status != MTLCommandBufferStatusCompleted) {
      return false;
    }

    const auto* const gpu_output =
        static_cast<const IccRgbaFloat*>([pixel_buffer contents]);
    for (std::size_t index = 0U; index < pixel_count; ++index) {
      const auto& pixel = gpu_output[index];
      if (!std::isfinite(pixel.red) || !std::isfinite(pixel.green) ||
          !std::isfinite(pixel.blue) || !std::isfinite(pixel.alpha) ||
          pixel.alpha != pixels[index].alpha) {
        return false;
      }
    }
    std::memcpy(pixels.data(), gpu_output, pixel_buffer_size);
    for (std::size_t index = 0U; index < exact_pixels.size(); ++index) {
      const auto& exact = exact_pixels[index];
      pixels[exact_indices[index]] = {
          .red = exact.red,
          .green = exact.green,
          .blue = exact.blue,
          .alpha = exact.alpha,
      };
    }
    if (apply_stats != nullptr) {
      apply_stats->lut_pixels = pixel_count - exact_pixels.size();
      apply_stats->exact_fallback_pixels = exact_pixels.size();
    }
    if (telemetry != nullptr) {
      telemetry->final_output_ms += std::chrono::duration_cast<
          std::chrono::milliseconds>(
          std::chrono::steady_clock::now() - stage_start)
                                        .count();
      telemetry->gpu_cpu_to_gpu_bytes += static_cast<std::int64_t>(
          pixel_buffer_size + resource_upload_bytes);
      telemetry->gpu_gpu_to_cpu_bytes +=
          static_cast<std::int64_t>(pixel_buffer_size);
      telemetry->gpu_command_buffer_count += 1;
      telemetry->gpu_kernel_dispatch_count += 1;
    }
    return true;
  }
}

bool MetalPipelineBackend::apply_ocio_project_gpu_program(
    std::vector<ColorPixel>* pixels,
    int width,
    int height,
    const OcioProjectGpuProgram& program,
    std::string* failure_reason,
    ColorAdjustmentTelemetry* telemetry) {
  const auto fail = [&](std::string reason) {
    if (failure_reason != nullptr) {
      *failure_reason = std::move(reason);
    }
    return false;
  };
  if (!available()) {
    return fail(unavailable_reason());
  }
  if (pixels == nullptr || width <= 0 || height <= 0 || !program.ready()) {
    return fail("invalid_ocio_project_gpu_request");
  }
  const auto pixel_count =
      static_cast<std::size_t>(width) * static_cast<std::size_t>(height);
  if (pixels->size() != pixel_count ||
      pixel_count > std::numeric_limits<std::uint32_t>::max()) {
    return fail("invalid_ocio_project_gpu_dimensions");
  }
  const auto& description = program.description();
  if (description.program_cache_key.empty() ||
      description.shader_sha256.size() != 64U ||
      description.resource_sha256.size() != 64U ||
      description.uniform_count != 0U ||
      description.uniform_buffer_bytes != 0U) {
    return fail("unsupported_ocio_project_gpu_program");
  }
  const auto full_shader = ocio_project_compute_shader_source(description);
  if (full_shader.empty()) {
    return fail("invalid_ocio_project_gpu_shader_contract");
  }
  const auto stage_start = std::chrono::steady_clock::now();
  auto resource_upload_bytes = std::size_t{0U};

  const std::scoped_lock program_lock(impl_->ocio_project_gpu_mutex);
  @autoreleasepool {
    auto cached = std::find_if(
        impl_->ocio_project_gpu_pipelines.begin(),
        impl_->ocio_project_gpu_pipelines.end(),
        [&](const Impl::OcioProjectGpuPipelineEntry& entry) {
          return entry.key == description.program_cache_key;
        });
    if (cached == impl_->ocio_project_gpu_pipelines.end()) {
      NSError* library_error = nil;
      const auto source = [NSString stringWithUTF8String:full_shader.c_str()];
      const auto library = [impl_->device
          newLibraryWithSource:source
                       options:color_compile_options()
                         error:&library_error];
      if (!library) {
        const auto detail = library_error != nil
                                ? [[library_error localizedDescription] UTF8String]
                                : "unknown";
        return fail(std::string("ocio_project_msl_compile_failed:") +
                    (detail != nullptr ? detail : "unknown"));
      }
      const auto function = [library
          newFunctionWithName:@"photo_editor_apply_ocio_project"];
      if (!function) {
        return fail("ocio_project_msl_function_unavailable");
      }
      NSError* pipeline_error = nil;
      const auto pipeline = [impl_->device
          newComputePipelineStateWithFunction:function
                                         error:&pipeline_error];
      if (!pipeline) {
        const auto detail = pipeline_error != nil
                                ? [[pipeline_error localizedDescription] UTF8String]
                                : "unknown";
        return fail(std::string("ocio_project_msl_pipeline_failed:") +
                    (detail != nullptr ? detail : "unknown"));
      }

      Impl::OcioProjectGpuPipelineEntry entry;
      entry.key = description.program_cache_key;
      entry.pipeline = pipeline;
      entry.last_use = ++impl_->ocio_project_gpu_use_counter;
      entry.textures.reserve(description.textures.size());
      entry.samplers.reserve(description.textures.size());
      for (const auto& texture : description.textures) {
        if ((texture.channels != 1U && texture.channels != 3U) ||
            texture.width == 0U || texture.height == 0U ||
            texture.depth == 0U || texture.values.empty()) {
          return fail("invalid_ocio_project_gpu_texture");
        }
        const auto pixel_format = texture.channels == 1U
                                      ? MTLPixelFormatR32Float
                                      : MTLPixelFormatRGBA32Float;
        auto* texture_descriptor = [[MTLTextureDescriptor alloc] init];
        texture_descriptor.textureType =
            texture.kind == OcioProjectGpuTextureKind::OneDimensional
                ? MTLTextureType1D
                : (texture.kind == OcioProjectGpuTextureKind::TwoDimensional
                       ? MTLTextureType2D
                       : MTLTextureType3D);
        texture_descriptor.pixelFormat = pixel_format;
        texture_descriptor.width = texture.width;
        texture_descriptor.height = texture.height;
        texture_descriptor.depth = texture.depth;
        texture_descriptor.mipmapLevelCount = 1U;
        texture_descriptor.storageMode = MTLStorageModeShared;
        texture_descriptor.usage = MTLTextureUsageShaderRead;
        const auto metal_texture =
            [impl_->device newTextureWithDescriptor:texture_descriptor];
        if (!metal_texture) {
          return fail("ocio_project_gpu_texture_allocation_failed");
        }
        const auto texel_count =
            texture.width * texture.height * texture.depth;
        const auto bytes_per_pixel = texture.channels == 1U
                                         ? sizeof(float)
                                         : sizeof(float) * 4U;
        std::vector<float> expanded;
        const float* upload_values = texture.values.data();
        if (texture.channels == 3U) {
          expanded.resize(texel_count * 4U);
          for (std::size_t index = 0U; index < texel_count; ++index) {
            expanded[index * 4U] = texture.values[index * 3U];
            expanded[index * 4U + 1U] = texture.values[index * 3U + 1U];
            expanded[index * 4U + 2U] = texture.values[index * 3U + 2U];
            expanded[index * 4U + 3U] = 1.0F;
          }
          upload_values = expanded.data();
        }
        const auto bytes_per_row = texture.width * bytes_per_pixel;
        const auto bytes_per_image = texture.height * bytes_per_row;
        [metal_texture
            replaceRegion:MTLRegionMake3D(
                              0U,
                              0U,
                              0U,
                              texture.width,
                              texture.height,
                              texture.depth)
             mipmapLevel:0U
                   slice:0U
               withBytes:upload_values
             bytesPerRow:bytes_per_row
           bytesPerImage:bytes_per_image];

        auto* sampler_descriptor = [[MTLSamplerDescriptor alloc] init];
        const auto nearest = texture.interpolation == "nearest";
        sampler_descriptor.minFilter =
            nearest ? MTLSamplerMinMagFilterNearest
                    : MTLSamplerMinMagFilterLinear;
        sampler_descriptor.magFilter = sampler_descriptor.minFilter;
        sampler_descriptor.mipFilter = MTLSamplerMipFilterNotMipmapped;
        sampler_descriptor.sAddressMode = MTLSamplerAddressModeClampToEdge;
        sampler_descriptor.tAddressMode = MTLSamplerAddressModeClampToEdge;
        sampler_descriptor.rAddressMode = MTLSamplerAddressModeClampToEdge;
        const auto sampler =
            [impl_->device newSamplerStateWithDescriptor:sampler_descriptor];
        if (!sampler) {
          return fail("ocio_project_gpu_sampler_allocation_failed");
        }
        entry.textures.push_back(metal_texture);
        entry.samplers.push_back(sampler);
        resource_upload_bytes += texel_count * bytes_per_pixel;
      }
      if (impl_->ocio_project_gpu_pipelines.size() >= 4U) {
        const auto least_recently_used = std::min_element(
            impl_->ocio_project_gpu_pipelines.begin(),
            impl_->ocio_project_gpu_pipelines.end(),
            [](const Impl::OcioProjectGpuPipelineEntry& left,
               const Impl::OcioProjectGpuPipelineEntry& right) {
              return left.last_use < right.last_use;
            });
        impl_->ocio_project_gpu_pipelines.erase(least_recently_used);
      }
      impl_->ocio_project_gpu_pipelines.push_back(std::move(entry));
      cached = std::prev(impl_->ocio_project_gpu_pipelines.end());
    } else {
      cached->last_use = ++impl_->ocio_project_gpu_use_counter;
    }

    const auto pixel_buffer_bytes = pixel_count * sizeof(ColorPixel);
    const auto pixel_buffer = [impl_->device
        newBufferWithBytes:pixels->data()
                    length:pixel_buffer_bytes
                   options:MTLResourceStorageModeShared];
    if (!pixel_buffer) {
      return fail("ocio_project_gpu_pixel_buffer_allocation_failed");
    }
    const auto command_buffer = [impl_->command_queue commandBuffer];
    const auto encoder = [command_buffer computeCommandEncoder];
    if (!command_buffer || !encoder) {
      return fail("ocio_project_gpu_command_encoder_unavailable");
    }
    [encoder setComputePipelineState:cached->pipeline];
    [encoder setBuffer:pixel_buffer offset:0U atIndex:0U];
    const auto metal_pixel_count = static_cast<std::uint32_t>(pixel_count);
    [encoder setBytes:&metal_pixel_count
               length:sizeof(metal_pixel_count)
              atIndex:1U];
    for (std::size_t index = 0U; index < description.textures.size(); ++index) {
      const auto binding = description.textures[index].binding_index;
      [encoder setTexture:cached->textures[index] atIndex:binding];
      [encoder setSamplerState:cached->samplers[index] atIndex:binding];
    }
    auto thread_group_size = cached->pipeline.maxTotalThreadsPerThreadgroup;
    thread_group_size = std::min<NSUInteger>(thread_group_size, 256U);
    [encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
         threadsPerThreadgroup:MTLSizeMake(thread_group_size, 1U, 1U)];
    [encoder endEncoding];
    [command_buffer commit];
    [command_buffer waitUntilCompleted];
    if (command_buffer.status != MTLCommandBufferStatusCompleted) {
      const auto error = command_buffer.error;
      const auto detail = error != nil ? [[error localizedDescription] UTF8String]
                                       : "unknown";
      return fail(std::string("ocio_project_gpu_dispatch_failed:") +
                  (detail != nullptr ? detail : "unknown"));
    }

    auto transformed = *pixels;
    std::memcpy(
        transformed.data(), [pixel_buffer contents], pixel_buffer_bytes);
    for (std::size_t index = 0U; index < transformed.size(); ++index) {
      if (!std::isfinite(transformed[index].red) ||
          !std::isfinite(transformed[index].green) ||
          !std::isfinite(transformed[index].blue) ||
          !std::isfinite(transformed[index].alpha) ||
          transformed[index].alpha != (*pixels)[index].alpha) {
        return fail("ocio_project_gpu_output_validation_failed");
      }
    }
    *pixels = std::move(transformed);
    if (failure_reason != nullptr) {
      failure_reason->clear();
    }
    if (telemetry != nullptr) {
      telemetry->final_output_ms += std::chrono::duration_cast<
          std::chrono::milliseconds>(
          std::chrono::steady_clock::now() - stage_start)
                                        .count();
      telemetry->gpu_cpu_to_gpu_bytes += static_cast<std::int64_t>(
          pixel_buffer_bytes + resource_upload_bytes);
      telemetry->gpu_gpu_to_cpu_bytes +=
          static_cast<std::int64_t>(pixel_buffer_bytes);
      telemetry->gpu_command_buffer_count += 1;
      telemetry->gpu_kernel_dispatch_count += 1;
    }
    return true;
  }
}

std::shared_ptr<const MetalWorkingSurface>
MetalPipelineBackend::publish_masks_and_color_lut_surface(
    std::span<const ColorPixel> pixels,
    int width,
    int height,
    const ColorAdjustmentState& state,
    const ColorLut3D& lut,
    const RenderSurfaceDescriptor& descriptor,
    ColorAdjustmentTelemetry* telemetry,
    CancellationToken cancellation,
    double scene_exposure_gain,
    bool apply_color_lut,
    const CompiledToneStageLut* tone_lut,
    const CompiledCurveStageLuts* curve_luts,
    const CompiledLookStageProgram* look_program,
    const CompiledUserLutStageProgram* user_lut_program) {
  const auto fail = [&](std::string reason) {
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason = std::move(reason);
    }
  };
  if (!available()) {
    fail(unavailable_reason());
    return {};
  }
  if (cancellation.cancelled()) {
    fail("fused_masks_color_lut_cancelled");
    return {};
  }
  if (pixels.empty() || (apply_color_lut && !lut.valid) ||
      (tone_lut != nullptr && !tone_lut->ready()) ||
      (curve_luts != nullptr && !curve_luts->ready()) ||
      (look_program != nullptr && !look_program->ready()) ||
      (user_lut_program != nullptr && !user_lut_program->ready()) ||
      width <= 0 || height <= 0 ||
      !std::isfinite(scene_exposure_gain) || scene_exposure_gain <= 0.0 ||
      descriptor.width != static_cast<std::uint32_t>(width) ||
      descriptor.height != static_cast<std::uint32_t>(height)) {
    fail("invalid_fused_masks_color_lut_request");
    return {};
  }
  const auto pixel_count =
      static_cast<std::size_t>(width) *
      static_cast<std::size_t>(height);
  const auto lut_edge =
      lut.size > 0
          ? static_cast<std::size_t>(lut.size)
          : std::size_t{0U};
  if (pixel_count >
          std::numeric_limits<std::size_t>::max() /
              sizeof(ColorPixel) ||
      pixel_count > std::numeric_limits<std::uint32_t>::max() ||
      pixels.size() != pixel_count) {
    fail("fused_masks_color_lut_pixel_count_mismatch");
    return {};
  }
  if (!std::ranges::all_of(pixels, [](const ColorPixel& pixel) {
        return std::isfinite(pixel.red) && std::isfinite(pixel.green) &&
               std::isfinite(pixel.blue) && std::isfinite(pixel.alpha);
      })) {
    fail("fused_masks_color_lut_source_non_finite");
    return {};
  }
  const auto geometry_program =
      compile_geometry_stage_program(state, width, height);
  if (!geometry_program.ready()) {
    fail("fused_geometry_program_invalid");
    return {};
  }
  const auto apply_geometry = geometry_program.active;
  const auto hdr_local_tone_program =
      compile_hdr_local_tone_program(state, width, height);
  if (!hdr_local_tone_program.ready()) {
    fail("fused_hdr_local_tone_program_invalid");
    return {};
  }
  const auto apply_hdr_local_tone = hdr_local_tone_program.active();
  if (apply_hdr_local_tone && tone_lut == nullptr) {
    fail("fused_hdr_local_tone_requires_tone_lut");
    return {};
  }
  std::shared_ptr<const CachedFillLayerPixels> cached_layer_pixels;
  {
    // Snapshot only the most recently used payload, preserving the existing
    // cache limits. The strong buffer owner pins shared storage even if another
    // publication evicts it before this program reaches the encoding lock.
    const std::scoped_lock cache_lock(impl_->color_lut_mutex);
    if (!impl_->layer_pixel_buffers.empty()) {
      const auto latest = std::max_element(impl_->layer_pixel_buffers.begin(), impl_->layer_pixel_buffers.end(),
          [](const auto& a, const auto& b) { return a.last_use < b.last_use; });
      auto owner = std::make_shared<Impl::LayerPixelBufferEntry>(*latest);
      cached_layer_pixels = std::make_shared<CachedFillLayerPixels>(CachedFillLayerPixels{
          .pixels = {static_cast<const ColorPixel*>([owner->buffer contents]),
              static_cast<std::size_t>(owner->bytes / sizeof(ColorPixel))},
          .owner = std::move(owner), .identity = latest->identity});
    }
  }
  const auto fill_layer_program = compile_fill_layer_program(state, width, height, std::move(cached_layer_pixels));
  if (!fill_layer_program.ready()) {
    fail("fused_fill_layer_program_invalid");
    return {};
  }
  const auto apply_fill_layers = fill_layer_program.active();
  const auto apply_layer_spatial_detail = std::ranges::any_of(
      fill_layer_program.layers.cbegin(),
      fill_layer_program.layers.cbegin() + fill_layer_program.layer_count,
      [](const auto& layer) { return layer.has_spatial_detail; });
  const auto apply_layer_fine_detail = std::ranges::any_of(
      fill_layer_program.layers.cbegin(),
      fill_layer_program.layers.cbegin() + fill_layer_program.layer_count,
      [](const auto& layer) { return layer.has_fine_detail; });
  const auto apply_layer_geometry = std::ranges::any_of(
      fill_layer_program.layers.cbegin(),
      fill_layer_program.layers.cbegin() + fill_layer_program.layer_count,
      [](const auto& layer) { return layer.has_geometry; });
  const auto apply_layer_user_lut = std::ranges::any_of(
      fill_layer_program.layers.cbegin(),
      fill_layer_program.layers.cbegin() + fill_layer_program.layer_count,
      [](const auto& layer) { return layer.has_user_lut; });
  const auto spatial_detail_program =
      compile_interactive_spatial_detail_program(state, width, height);
  if (!spatial_detail_program.ready()) {
    fail("fused_spatial_detail_program_invalid");
    return {};
  }
  const auto apply_spatial_detail = spatial_detail_program.active();
  const auto fine_detail_program =
      compile_fine_detail_program(state, width, height);
  if (!fine_detail_program.ready()) {
    fail("fused_fine_detail_program_invalid");
    return {};
  }
  const auto apply_fine_detail = fine_detail_program.active();
  if (tone_lut != nullptr &&
      (!std::ranges::all_of(
           tone_lut->samples,
           [](float sample) { return std::isfinite(sample); }) ||
       !std::ranges::all_of(
           tone_lut->luminance_coefficients,
           [](float coefficient) { return std::isfinite(coefficient); }) ||
       !std::isfinite(tone_lut->stop_step) || tone_lut->stop_step <= 0.0F ||
       !std::isfinite(tone_lut->output_headroom) ||
       tone_lut->output_headroom < 1.0F)) {
    fail("fused_tone_lut_invalid");
    return {};
  }
  if (curve_luts != nullptr) {
    const auto curves = std::array{
        &curve_luts->parametric,
        &curve_luts->master,
        &curve_luts->luma,
        &curve_luts->red,
        &curve_luts->green,
        &curve_luts->blue,
    };
    const auto curves_finite = std::ranges::all_of(
        curves,
        [](const auto* curve) {
          return std::ranges::all_of(
              *curve, [](float sample) { return std::isfinite(sample); });
        });
    if (!curves_finite ||
        !std::ranges::all_of(
            curve_luts->luminance_coefficients,
            [](float coefficient) { return std::isfinite(coefficient); }) ||
        !std::isfinite(curve_luts->output_headroom) ||
        curve_luts->output_headroom < 1.0F) {
      fail("fused_curve_luts_invalid");
      return {};
    }
  }
  if (look_program != nullptr) {
    const auto finite_values = [](const auto& values) {
      return std::ranges::all_of(
          values, [](auto value) { return std::isfinite(value); });
    };
    if (!finite_values(look_program->rgb_to_xyz_d65.values) ||
        !finite_values(look_program->xyz_d65_to_rgb.values) ||
        !finite_values(look_program->luminance_coefficients) ||
        !finite_values(look_program->rgb_mixer) ||
        !finite_values(look_program->black_and_white_mixer) ||
        !finite_values(look_program->grading_hue) ||
        !finite_values(look_program->grading_saturation) ||
        !finite_values(look_program->grading_luminance) ||
        !finite_values(look_program->mixer_hue) ||
        !finite_values(look_program->mixer_saturation) ||
        !finite_values(look_program->mixer_luminance) ||
        !finite_values(look_program->selective_cyan) ||
        !finite_values(look_program->selective_magenta) ||
        !finite_values(look_program->selective_yellow) ||
        !finite_values(look_program->selective_black) ||
        !finite_values(look_program->harmony_anchors) ||
        !std::isfinite(look_program->saturation_strength) ||
        !std::isfinite(look_program->vibrance_strength) ||
        !std::isfinite(look_program->grading_amount) ||
        !std::isfinite(look_program->grading_balance) ||
        !std::isfinite(look_program->harmony_strength) ||
        !std::isfinite(look_program->replacement_source_hue) ||
        !std::isfinite(look_program->replacement_target_oklab_hue) ||
        !std::isfinite(look_program->replacement_range) ||
        !std::isfinite(look_program->replacement_softness) ||
        !std::isfinite(look_program->replacement_strength) ||
        !std::isfinite(look_program->skin_hue) ||
        !std::isfinite(look_program->skin_range) ||
        !std::isfinite(look_program->skin_strength) ||
        !std::isfinite(look_program->output_headroom) ||
        look_program->output_headroom < 1.0F ||
        look_program->harmony_anchor_count > look_program->harmony_anchors.size() ||
        look_program->replacement_preserve_luminance > 1U ||
        look_program->replacement_preserve_saturation > 1U) {
      fail("fused_look_program_invalid");
      return {};
    }
  }
  if (apply_color_lut && (lut_edge < 2U ||
      lut_edge >
          std::numeric_limits<std::size_t>::max() /
              lut_edge ||
      lut_edge * lut_edge >
          std::numeric_limits<std::size_t>::max() /
              lut_edge ||
      lut.table.size() !=
          lut_edge * lut_edge * lut_edge)) {
    fail("fused_masks_color_lut_shape_invalid");
    return {};
  }

  @autoreleasepool {
    std::unique_lock color_lut_lock(impl_->color_lut_mutex);
    auto fill_mask_upload_bytes = std::size_t{0U};
    id<MTLBuffer> fill_mask_buffer = nil;
    if (apply_fill_layers && fill_layer_program.mask_data.empty()) {
      fill_mask_buffer = [impl_->device
          newBufferWithLength:1U options:MTLResourceStorageModeShared];
    } else if (apply_fill_layers) {
      const auto match = std::find_if(
          impl_->fill_mask_buffers.begin(), impl_->fill_mask_buffers.end(),
          [&](const auto& entry) {
            return entry.identity == fill_layer_program.mask_identity;
          });
      if (match != impl_->fill_mask_buffers.end()) {
        match->last_use = ++impl_->fill_mask_use_counter;
        fill_mask_buffer = match->buffer;
      } else {
        const auto mask_bytes = fill_layer_program.mask_data.size();
        fill_mask_buffer = [impl_->device
            newBufferWithLength:mask_bytes options:MTLResourceStorageModeShared];
        if (fill_mask_buffer != nil) {
          std::memcpy(
              [fill_mask_buffer contents],
              fill_layer_program.mask_data.data(),
              mask_bytes);
          fill_mask_upload_bytes = mask_bytes;
        }
        if (fill_mask_buffer != nil &&
            mask_bytes <= Impl::kMaximumFillMaskBufferBytes) {
          while (!impl_->fill_mask_buffers.empty() &&
                 (impl_->fill_mask_buffers.size() >=
                      Impl::kMaximumFillMaskBufferEntries ||
                  impl_->fill_mask_buffer_bytes + mask_bytes >
                      Impl::kMaximumFillMaskBufferBytes)) {
            const auto oldest = std::min_element(
                impl_->fill_mask_buffers.begin(), impl_->fill_mask_buffers.end(),
                [](const auto& left, const auto& right) {
                  return left.last_use < right.last_use;
                });
            impl_->fill_mask_buffer_bytes -= oldest->bytes;
            impl_->fill_mask_buffers.erase(oldest);
          }
          impl_->fill_mask_buffers.push_back({
              .identity = fill_layer_program.mask_identity,
              .buffer = fill_mask_buffer,
              .bytes = static_cast<std::uint64_t>(mask_bytes),
              .last_use = ++impl_->fill_mask_use_counter,
          });
          impl_->fill_mask_buffer_bytes += mask_bytes;
        }
      }
    }
    auto layer_pixel_upload_bytes = std::size_t{0U};
    id<MTLBuffer> layer_pixel_buffer = nil;
    if (apply_fill_layers && fill_layer_program.pixel_data_view().empty()) {
      layer_pixel_buffer = [impl_->device
          newBufferWithLength:sizeof(ColorPixel) options:MTLResourceStorageModeShared];
    } else if (apply_fill_layers) {
      const auto match = std::find_if(
          impl_->layer_pixel_buffers.begin(), impl_->layer_pixel_buffers.end(),
          [&](const auto& entry) {
            return entry.identity == fill_layer_program.pixel_identity;
          });
      if (match != impl_->layer_pixel_buffers.end()) {
        match->last_use = ++impl_->layer_pixel_use_counter;
        layer_pixel_buffer = match->buffer;
      } else {
        const auto payload_bytes =
            fill_layer_program.pixel_data_view().size() * sizeof(ColorPixel);
        layer_pixel_buffer = [impl_->device
            newBufferWithLength:payload_bytes options:MTLResourceStorageModeShared];
        if (layer_pixel_buffer != nil) {
          std::memcpy(
              [layer_pixel_buffer contents],
              fill_layer_program.pixel_data_view().data(),
              payload_bytes);
          layer_pixel_upload_bytes = payload_bytes;
        }
        if (layer_pixel_buffer != nil &&
            payload_bytes <= Impl::kMaximumLayerPixelBufferBytes) {
          while (!impl_->layer_pixel_buffers.empty() &&
                 (impl_->layer_pixel_buffers.size() >=
                      Impl::kMaximumLayerPixelBufferEntries ||
                  impl_->layer_pixel_buffer_bytes + payload_bytes >
                      Impl::kMaximumLayerPixelBufferBytes)) {
            const auto oldest = std::min_element(
                impl_->layer_pixel_buffers.begin(),
                impl_->layer_pixel_buffers.end(),
                [](const auto& left, const auto& right) {
                  return left.last_use < right.last_use;
                });
            impl_->layer_pixel_buffer_bytes -= oldest->bytes;
            impl_->layer_pixel_buffers.erase(oldest);
          }
          impl_->layer_pixel_buffers.push_back({
              .identity = fill_layer_program.pixel_identity,
              .buffer = layer_pixel_buffer,
              .bytes = static_cast<std::uint64_t>(payload_bytes),
              .last_use = ++impl_->layer_pixel_use_counter,
          });
          impl_->layer_pixel_buffer_bytes += payload_bytes;
        }
      }
    }
    auto layer_tone_upload_bytes = std::size_t{0U};
    id<MTLBuffer> layer_tone_buffer = nil;
    if (apply_fill_layers && fill_layer_program.tone_float_count == 0U) {
      layer_tone_buffer = [impl_->device
          newBufferWithLength:sizeof(float) options:MTLResourceStorageModeShared];
    } else if (apply_fill_layers) {
      const auto match = std::find_if(
          impl_->layer_tone_buffers.begin(), impl_->layer_tone_buffers.end(),
          [&](const auto& entry) {
            return entry.identity == fill_layer_program.tone_identity;
          });
      if (match != impl_->layer_tone_buffers.end()) {
        match->last_use = ++impl_->layer_tone_use_counter;
        layer_tone_buffer = match->buffer;
      } else {
        const auto payload_bytes =
            fill_layer_program.tone_float_count * sizeof(float);
        layer_tone_buffer = [impl_->device
            newBufferWithLength:payload_bytes options:MTLResourceStorageModeShared];
        if (layer_tone_buffer != nil) {
          auto* destination = static_cast<std::byte*>([layer_tone_buffer contents]);
          for (auto index = std::size_t{0U};
               index < fill_layer_program.layer_count; ++index) {
            if (fill_layer_program.layers[index].has_tone) {
              const auto& tone = fill_layer_program.tone_luts[index];
              std::memcpy(
                  destination + fill_layer_program.layers[index].tone_offset *
                                    sizeof(float),
                  tone.samples.data(), tone.samples.size() * sizeof(float));
            }
            if (fill_layer_program.layers[index].has_advanced_tone) {
              const auto& tone = fill_layer_program.advanced_tone_luts[index];
              std::memcpy(
                  destination +
                      fill_layer_program.layers[index].advanced_tone_offset *
                          sizeof(float),
                  tone.samples.data(), tone.samples.size() * sizeof(float));
            }
          }
          layer_tone_upload_bytes = payload_bytes;
        }
        if (layer_tone_buffer != nil &&
            payload_bytes <= Impl::kMaximumLayerToneBufferBytes) {
          while (!impl_->layer_tone_buffers.empty() &&
                 (impl_->layer_tone_buffers.size() >=
                      Impl::kMaximumLayerToneBufferEntries ||
                  impl_->layer_tone_buffer_bytes + payload_bytes >
                      Impl::kMaximumLayerToneBufferBytes)) {
            const auto oldest = std::min_element(
                impl_->layer_tone_buffers.begin(),
                impl_->layer_tone_buffers.end(),
                [](const auto& left, const auto& right) {
                  return left.last_use < right.last_use;
                });
            impl_->layer_tone_buffer_bytes -= oldest->bytes;
            impl_->layer_tone_buffers.erase(oldest);
          }
          impl_->layer_tone_buffers.push_back({
              .identity = fill_layer_program.tone_identity,
              .buffer = layer_tone_buffer,
              .bytes = static_cast<std::uint64_t>(payload_bytes),
              .last_use = ++impl_->layer_tone_use_counter,
          });
          impl_->layer_tone_buffer_bytes += payload_bytes;
        }
      }
    }
    auto layer_curve_upload_bytes = std::size_t{0U};
    id<MTLBuffer> layer_curve_buffer = nil;
    if (apply_fill_layers && fill_layer_program.curve_float_count == 0U) {
      layer_curve_buffer = [impl_->device
          newBufferWithLength:sizeof(float) options:MTLResourceStorageModeShared];
    } else if (apply_fill_layers) {
      const auto match = std::find_if(
          impl_->layer_curve_buffers.begin(), impl_->layer_curve_buffers.end(),
          [&](const auto& entry) {
            return entry.identity == fill_layer_program.curve_identity;
          });
      if (match != impl_->layer_curve_buffers.end()) {
        match->last_use = ++impl_->layer_curve_use_counter;
        layer_curve_buffer = match->buffer;
      } else {
        const auto payload_bytes =
            fill_layer_program.curve_float_count * sizeof(float);
        layer_curve_buffer = [impl_->device
            newBufferWithLength:payload_bytes options:MTLResourceStorageModeShared];
        if (layer_curve_buffer != nil) {
          auto* destination = static_cast<std::byte*>(
              [layer_curve_buffer contents]);
          for (auto index = std::size_t{0U};
               index < fill_layer_program.layer_count; ++index) {
            if (!fill_layer_program.layers[index].has_curves) continue;
            const auto& layer = fill_layer_program.layers[index];
            const auto& curves = fill_layer_program.curve_luts[index];
            const auto vectors = std::array{
                &curves.parametric, &curves.master, &curves.luma,
                &curves.red, &curves.green, &curves.blue};
            for (auto curve = std::size_t{0U}; curve < vectors.size(); ++curve) {
              if (vectors[curve]->empty()) continue;
              std::memcpy(
                  destination + layer.curve_offsets[curve] * sizeof(float),
                  vectors[curve]->data(),
                  vectors[curve]->size() * sizeof(float));
            }
          }
          layer_curve_upload_bytes = payload_bytes;
        }
        if (layer_curve_buffer != nil &&
            payload_bytes <= Impl::kMaximumLayerCurveBufferBytes) {
          while (!impl_->layer_curve_buffers.empty() &&
                 (impl_->layer_curve_buffers.size() >=
                      Impl::kMaximumLayerCurveBufferEntries ||
                  impl_->layer_curve_buffer_bytes + payload_bytes >
                      Impl::kMaximumLayerCurveBufferBytes)) {
            const auto oldest = std::min_element(
                impl_->layer_curve_buffers.begin(),
                impl_->layer_curve_buffers.end(),
                [](const auto& left, const auto& right) {
                  return left.last_use < right.last_use;
                });
            impl_->layer_curve_buffer_bytes -= oldest->bytes;
            impl_->layer_curve_buffers.erase(oldest);
          }
          impl_->layer_curve_buffers.push_back({
              .identity = fill_layer_program.curve_identity,
              .buffer = layer_curve_buffer,
              .bytes = static_cast<std::uint64_t>(payload_bytes),
              .last_use = ++impl_->layer_curve_use_counter,
          });
          impl_->layer_curve_buffer_bytes += payload_bytes;
        }
      }
    }
    auto layer_look_upload_bytes = std::size_t{0U};
    id<MTLBuffer> layer_look_buffer = nil;
    if (apply_fill_layers && fill_layer_program.downstream_look_identity == 0U) {
      layer_look_buffer = [impl_->device
          newBufferWithLength:sizeof(LookStageUniforms)
                       options:MTLResourceStorageModeShared];
    } else if (apply_fill_layers) {
      const auto match = std::find_if(
          impl_->layer_look_buffers.begin(), impl_->layer_look_buffers.end(),
          [&](const auto& entry) {
            return entry.identity == fill_layer_program.downstream_look_identity;
          });
      if (match != impl_->layer_look_buffers.end()) {
        match->last_use = ++impl_->layer_look_use_counter;
        layer_look_buffer = match->buffer;
      } else {
        auto payload = std::vector<LookStageUniforms>(
            fill_layer_program.layer_count);
        for (auto index = std::size_t{0U};
             index < fill_layer_program.layer_count; ++index) {
          if (fill_layer_program.layers[index].has_downstream_look) {
            payload[index] = make_look_stage_uniforms(
                fill_layer_program.downstream_look_programs[index]);
          }
        }
        const auto payload_bytes = payload.size() * sizeof(LookStageUniforms);
        layer_look_buffer = [impl_->device
            newBufferWithBytes:payload.data()
                         length:payload_bytes
                        options:MTLResourceStorageModeShared];
        if (layer_look_buffer != nil) layer_look_upload_bytes = payload_bytes;
        if (layer_look_buffer != nil &&
            payload_bytes <= Impl::kMaximumLayerLookBufferBytes) {
          while (!impl_->layer_look_buffers.empty() &&
                 (impl_->layer_look_buffers.size() >=
                      Impl::kMaximumLayerLookBufferEntries ||
                  impl_->layer_look_buffer_bytes + payload_bytes >
                      Impl::kMaximumLayerLookBufferBytes)) {
            const auto oldest = std::min_element(
                impl_->layer_look_buffers.begin(),
                impl_->layer_look_buffers.end(),
                [](const auto& left, const auto& right) {
                  return left.last_use < right.last_use;
                });
            impl_->layer_look_buffer_bytes -= oldest->bytes;
            impl_->layer_look_buffers.erase(oldest);
          }
          impl_->layer_look_buffers.push_back({
              .identity = fill_layer_program.downstream_look_identity,
              .buffer = layer_look_buffer,
              .bytes = static_cast<std::uint64_t>(payload_bytes),
              .last_use = ++impl_->layer_look_use_counter,
          });
          impl_->layer_look_buffer_bytes += payload_bytes;
        }
      }
    }
    auto lut_upload_bytes = std::size_t{0U};
    const auto buffer_for_color_lut = [&](const ColorLut3D& active_lut) {
      const auto table_bytes = active_lut.table.size() * sizeof(ColorPixel);
      const auto shaper_bytes =
          active_lut.shaper_table.size() * sizeof(ColorPixel);
      const auto active_lut_bytes = table_bytes + shaper_bytes;
      const auto cached_lut = std::find_if(
          impl_->color_lut_buffers.begin(), impl_->color_lut_buffers.end(),
          [&](const Impl::ColorLutBufferEntry& entry) {
            return active_lut.cache_identity != 0U &&
                   entry.identity == active_lut.cache_identity;
          });
      if (cached_lut != impl_->color_lut_buffers.end()) {
        cached_lut->last_use = ++impl_->color_lut_use_counter;
        return cached_lut->buffer;
      }
      id<MTLBuffer> active_buffer = [impl_->device
          newBufferWithLength:active_lut_bytes
                      options:MTLResourceStorageModeShared];
      if (active_buffer == nil) return active_buffer;
      auto* buffer_bytes = static_cast<std::byte*>([active_buffer contents]);
      if (table_bytes > 0U) {
        std::memcpy(buffer_bytes, active_lut.table.data(), table_bytes);
      }
      if (shaper_bytes > 0U) {
        std::memcpy(
            buffer_bytes + table_bytes,
            active_lut.shaper_table.data(),
            shaper_bytes);
      }
      lut_upload_bytes += active_lut_bytes;
      if (active_lut.cache_identity == 0U ||
          active_lut_bytes > Impl::kMaximumColorLutBufferBytes) {
        return active_buffer;
      }
      while (!impl_->color_lut_buffers.empty() &&
             (impl_->color_lut_buffers.size() >=
                  Impl::kMaximumColorLutBufferEntries ||
              impl_->color_lut_buffer_bytes + active_lut_bytes >
                  Impl::kMaximumColorLutBufferBytes)) {
        const auto least_recently_used = std::min_element(
            impl_->color_lut_buffers.begin(), impl_->color_lut_buffers.end(),
            [](const auto& left, const auto& right) {
              return left.last_use < right.last_use;
            });
        impl_->color_lut_buffer_bytes -= least_recently_used->bytes;
        impl_->color_lut_buffers.erase(least_recently_used);
      }
      impl_->color_lut_buffers.push_back({
          .identity = active_lut.cache_identity,
          .buffer = active_buffer,
          .bytes = active_lut_bytes,
          .last_use = ++impl_->color_lut_use_counter,
      });
      impl_->color_lut_buffer_bytes += active_lut_bytes;
      return active_buffer;
    };
    id<MTLBuffer> lut_buffer =
        apply_color_lut ? buffer_for_color_lut(lut) : nil;
    auto user_lut_buffers = std::vector<id<MTLBuffer>>{};
    if (user_lut_program != nullptr) {
      user_lut_buffers.reserve(user_lut_program->luts.size());
      for (const auto& user_lut : user_lut_program->luts) {
        user_lut_buffers.push_back(buffer_for_color_lut(user_lut.lut));
      }
    }
    auto layer_user_lut_buffers = std::array<
        std::vector<id<MTLBuffer>>,
        CompiledFillLayerProgram::kMaximumLayers>{};
    if (apply_layer_user_lut) {
      for (auto layer_index = std::size_t{0U};
           layer_index < fill_layer_program.layer_count; ++layer_index) {
        const auto& program = fill_layer_program.user_lut_programs[layer_index];
        if (!program.active()) continue;
        auto& buffers = layer_user_lut_buffers[layer_index];
        buffers.reserve(program.luts.size());
        for (const auto& user_lut : program.luts) {
          buffers.push_back(buffer_for_color_lut(user_lut.lut));
        }
      }
    }
    auto tone_lut_upload_bytes = std::size_t{0U};
    id<MTLBuffer> tone_lut_buffer = nil;
    if (tone_lut != nullptr) {
      const auto tone_lut_buffer_size =
          tone_lut->samples.size() * sizeof(float);
      const auto cached_tone_lut = std::find_if(
          impl_->tone_lut_buffers.begin(),
          impl_->tone_lut_buffers.end(),
          [&](const Impl::ToneLutBufferEntry& entry) {
            return entry.identity == tone_lut->cache_identity;
          });
      if (cached_tone_lut != impl_->tone_lut_buffers.end()) {
        cached_tone_lut->last_use = ++impl_->tone_lut_use_counter;
        tone_lut_buffer = cached_tone_lut->buffer;
      } else {
        tone_lut_buffer = [impl_->device
            newBufferWithLength:tone_lut_buffer_size
                        options:MTLResourceStorageModeShared];
        if (tone_lut_buffer != nil) {
          std::memcpy(
              [tone_lut_buffer contents],
              tone_lut->samples.data(),
              tone_lut_buffer_size);
          tone_lut_upload_bytes = tone_lut_buffer_size;
        }
        if (tone_lut_buffer != nil &&
            tone_lut_buffer_size <= Impl::kMaximumToneLutBufferBytes) {
          while (!impl_->tone_lut_buffers.empty() &&
                 (impl_->tone_lut_buffers.size() >=
                      Impl::kMaximumToneLutBufferEntries ||
                  impl_->tone_lut_buffer_bytes + tone_lut_buffer_size >
                      Impl::kMaximumToneLutBufferBytes)) {
            const auto least_recently_used = std::min_element(
                impl_->tone_lut_buffers.begin(),
                impl_->tone_lut_buffers.end(),
                [](const auto& left, const auto& right) {
                  return left.last_use < right.last_use;
                });
            impl_->tone_lut_buffer_bytes -= least_recently_used->bytes;
            impl_->tone_lut_buffers.erase(least_recently_used);
          }
          impl_->tone_lut_buffers.push_back({
              .identity = tone_lut->cache_identity,
              .buffer = tone_lut_buffer,
              .bytes = static_cast<std::uint64_t>(tone_lut_buffer_size),
              .last_use = ++impl_->tone_lut_use_counter,
          });
          impl_->tone_lut_buffer_bytes += tone_lut_buffer_size;
        }
      }
    }
    auto curve_lut_upload_bytes = std::size_t{0U};
    id<MTLBuffer> curve_lut_buffer = nil;
    if (curve_luts != nullptr) {
      constexpr auto kCurveBlockCount = std::size_t{6U};
      const auto curve_lut_buffer_size =
          kCurveBlockCount *
          static_cast<std::size_t>(CompiledCurveStageLuts::kSampleCount) *
          sizeof(float);
      const auto cached_curve_lut = std::find_if(
          impl_->curve_lut_buffers.begin(),
          impl_->curve_lut_buffers.end(),
          [&](const Impl::CurveLutBufferEntry& entry) {
            return entry.identity == curve_luts->cache_identity;
          });
      if (cached_curve_lut != impl_->curve_lut_buffers.end()) {
        cached_curve_lut->last_use = ++impl_->curve_lut_use_counter;
        curve_lut_buffer = cached_curve_lut->buffer;
      } else {
        curve_lut_buffer = [impl_->device
            newBufferWithLength:curve_lut_buffer_size
                        options:MTLResourceStorageModeShared];
        if (curve_lut_buffer != nil) {
          auto* destination =
              static_cast<float*>([curve_lut_buffer contents]);
          std::fill_n(
              destination,
              kCurveBlockCount * static_cast<std::size_t>(
                                     CompiledCurveStageLuts::kSampleCount),
              0.0F);
          const auto blocks = std::array{
              &curve_luts->parametric,
              &curve_luts->master,
              &curve_luts->luma,
              &curve_luts->red,
              &curve_luts->green,
              &curve_luts->blue,
          };
          for (auto block = std::size_t{0U}; block < blocks.size(); ++block) {
            if (!blocks[block]->empty()) {
              std::copy(
                  blocks[block]->cbegin(),
                  blocks[block]->cend(),
                  destination + block * static_cast<std::size_t>(
                                            CompiledCurveStageLuts::kSampleCount));
            }
          }
          curve_lut_upload_bytes = curve_lut_buffer_size;
        }
        if (curve_lut_buffer != nil &&
            curve_lut_buffer_size <= Impl::kMaximumCurveLutBufferBytes) {
          while (!impl_->curve_lut_buffers.empty() &&
                 (impl_->curve_lut_buffers.size() >=
                      Impl::kMaximumCurveLutBufferEntries ||
                  impl_->curve_lut_buffer_bytes + curve_lut_buffer_size >
                      Impl::kMaximumCurveLutBufferBytes)) {
            const auto least_recently_used = std::min_element(
                impl_->curve_lut_buffers.begin(),
                impl_->curve_lut_buffers.end(),
                [](const auto& left, const auto& right) {
                  return left.last_use < right.last_use;
                });
            impl_->curve_lut_buffer_bytes -= least_recently_used->bytes;
            impl_->curve_lut_buffers.erase(least_recently_used);
          }
          impl_->curve_lut_buffers.push_back({
              .identity = curve_luts->cache_identity,
              .buffer = curve_lut_buffer,
              .bytes = static_cast<std::uint64_t>(curve_lut_buffer_size),
              .last_use = ++impl_->curve_lut_use_counter,
          });
          impl_->curve_lut_buffer_bytes += curve_lut_buffer_size;
        }
      }
    }
    // Local ARC owners pin immutable cached buffers across eviction by another
    // render. Per-flight allocations, source upload, and command encoding do not
    // access mutable cache state and must not serialize on the cache mutex.
    color_lut_lock.unlock();
    const auto buffer_size = pixel_count * sizeof(float) * 4;
    id<MTLBuffer> pixel_buffer = [impl_->device newBufferWithLength:buffer_size
                                                            options:MTLResourceStorageModeShared];
    id<MTLBuffer> geometry_buffer =
        (apply_geometry || apply_layer_geometry)
            ? [impl_->device newBufferWithLength:buffer_size
                                         options:MTLResourceStorageModeShared]
            : nil;
    id<MTLBuffer> layer_alpha_buffer = apply_fill_layers
        ? [impl_->device newBufferWithLength:pixel_count * sizeof(float)
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> layer_intermediate_buffer = apply_fill_layers
        ? [impl_->device newBufferWithLength:buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    const auto scalar_buffer_size = pixel_count * sizeof(float);
    id<MTLBuffer> hdr_local_log_buffer = apply_hdr_local_tone
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> hdr_local_scratch_buffer = apply_hdr_local_tone
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> hdr_local_blur_buffer = apply_hdr_local_tone
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    const auto need_spatial_buffers = apply_spatial_detail ||
                                      apply_layer_spatial_detail ||
                                      apply_layer_fine_detail;
    const auto need_fine_buffers =
        apply_fine_detail || apply_layer_fine_detail || apply_layer_spatial_detail;
    id<MTLBuffer> spatial_luminance_buffer = need_spatial_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> spatial_scratch_buffer = need_spatial_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> spatial_texture_buffer = need_spatial_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> spatial_clarity_buffer = need_spatial_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> spatial_haze_buffer = need_spatial_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> detail_lightness_buffer = need_fine_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> detail_chroma_a_buffer = need_fine_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> detail_chroma_b_buffer = need_fine_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> detail_scratch_buffer = need_fine_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> detail_blur_a_buffer = need_fine_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    id<MTLBuffer> detail_blur_b_buffer = need_fine_buffers
        ? [impl_->device newBufferWithLength:scalar_buffer_size
                                     options:MTLResourceStorageModePrivate]
        : nil;
    if (!pixel_buffer ||
        ((apply_geometry || apply_layer_geometry) && !geometry_buffer) ||
        (apply_fill_layers &&
         (!fill_mask_buffer || !layer_pixel_buffer || !layer_tone_buffer ||
          !layer_curve_buffer || !layer_look_buffer || !layer_alpha_buffer ||
          !layer_intermediate_buffer)) ||
        (apply_hdr_local_tone &&
         (!hdr_local_log_buffer || !hdr_local_scratch_buffer ||
          !hdr_local_blur_buffer)) ||
        (need_spatial_buffers &&
         (!spatial_luminance_buffer || !spatial_scratch_buffer ||
          !spatial_texture_buffer || !spatial_clarity_buffer ||
          !spatial_haze_buffer)) ||
        (need_fine_buffers &&
         (!detail_lightness_buffer || !detail_chroma_a_buffer ||
          !detail_chroma_b_buffer || !detail_scratch_buffer ||
          !detail_blur_a_buffer || !detail_blur_b_buffer)) ||
        (apply_color_lut && !lut_buffer) ||
        (tone_lut != nullptr && !tone_lut_buffer) ||
        (curve_luts != nullptr && !curve_lut_buffer) ||
        std::ranges::any_of(
            user_lut_buffers,
            [](id<MTLBuffer> buffer) { return buffer == nil; }) ||
        std::ranges::any_of(
            layer_user_lut_buffers,
            [](const auto& buffers) {
              return std::ranges::any_of(
                  buffers, [](id<MTLBuffer> buffer) { return buffer == nil; });
            })) {
      fail("fused_masks_color_lut_buffer_allocation_failed");
      return {};
    }

    auto* pixel_data = static_cast<float*>([pixel_buffer contents]);
    std::memcpy(pixel_data, pixels.data(), buffer_size);

    id<MTLCommandBuffer> command_buffer = [impl_->command_queue commandBuffer];
    if (!command_buffer) {
      fail("fused_masks_color_lut_command_buffer_unavailable");
      return {};
    }

    auto kernel_dispatch_count = std::int64_t{0};
    if (std::abs(scene_exposure_gain - 1.0) > 1.0e-12) {
      const auto exposure_uniforms = SceneExposureUniforms{
          .gain = static_cast<float>(scene_exposure_gain),
          .pixel_count = static_cast<std::uint32_t>(pixel_count),
      };
      id<MTLComputeCommandEncoder> exposure_encoder =
          [command_buffer computeCommandEncoder];
      [exposure_encoder setComputePipelineState:impl_->scene_exposure_pipeline];
      [exposure_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
      [exposure_encoder setBytes:&exposure_uniforms
                          length:sizeof(exposure_uniforms)
                         atIndex:1];
      auto exposure_group_size =
          impl_->scene_exposure_pipeline.maxTotalThreadsPerThreadgroup;
      exposure_group_size = std::min<NSUInteger>(exposure_group_size, 256U);
      [exposure_encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
                   threadsPerThreadgroup:MTLSizeMake(exposure_group_size, 1U, 1U)];
      [exposure_encoder endEncoding];
      ++kernel_dispatch_count;
    }
    if (tone_lut != nullptr) {
      const auto tone_uniforms = ToneStageUniforms{
          .luminance_red = tone_lut->luminance_coefficients[0],
          .luminance_green = tone_lut->luminance_coefficients[1],
          .luminance_blue = tone_lut->luminance_coefficients[2],
          .minimum_stops = CompiledToneStageLut::kMinimumStops,
          .stop_step = tone_lut->stop_step,
          .middle_gray = CompiledToneStageLut::kMiddleGray,
          .output_headroom = tone_lut->output_headroom,
          .sample_count = static_cast<std::uint32_t>(tone_lut->samples.size()),
          .pixel_count = static_cast<std::uint32_t>(pixel_count),
      };
      id<MTLComputeCommandEncoder> tone_encoder =
          [command_buffer computeCommandEncoder];
      [tone_encoder setComputePipelineState:impl_->tone_stage_pipeline];
      [tone_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
      [tone_encoder setBuffer:tone_lut_buffer offset:0 atIndex:1];
      [tone_encoder setBytes:&tone_uniforms
                      length:sizeof(tone_uniforms)
                     atIndex:2];
      auto tone_group_size =
          impl_->tone_stage_pipeline.maxTotalThreadsPerThreadgroup;
      tone_group_size = std::min<NSUInteger>(tone_group_size, 256U);
      [tone_encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
              threadsPerThreadgroup:MTLSizeMake(tone_group_size, 1U, 1U)];
      [tone_encoder endEncoding];
      ++kernel_dispatch_count;
    }
    if (apply_hdr_local_tone) {
      const auto uniforms = HdrLocalToneUniforms{
          .luminance_red = hdr_local_tone_program.luminance_coefficients[0],
          .luminance_green = hdr_local_tone_program.luminance_coefficients[1],
          .luminance_blue = hdr_local_tone_program.luminance_coefficients[2],
          .strength = hdr_local_tone_program.strength,
          .output_headroom = hdr_local_tone_program.output_headroom,
          .width = hdr_local_tone_program.width,
          .height = hdr_local_tone_program.height,
      };
      const auto dispatch_hdr_local = [&](id<MTLComputePipelineState> pipeline,
                                           const auto& buffers,
                                           NSUInteger uniforms_index,
                                           const auto& active_uniforms) {
        id<MTLComputeCommandEncoder> encoder =
            [command_buffer computeCommandEncoder];
        [encoder setComputePipelineState:pipeline];
        for (auto index = std::size_t{0U}; index < buffers.size(); ++index) {
          [encoder setBuffer:buffers[index]
                      offset:0
                     atIndex:static_cast<NSUInteger>(index)];
        }
        [encoder setBytes:&active_uniforms
                   length:sizeof(active_uniforms)
                  atIndex:uniforms_index];
        auto group_size = pipeline.maxTotalThreadsPerThreadgroup;
        group_size = std::min<NSUInteger>(group_size, 256U);
        [encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
             threadsPerThreadgroup:MTLSizeMake(group_size, 1U, 1U)];
        [encoder endEncoding];
        ++kernel_dispatch_count;
      };
      dispatch_hdr_local(
          impl_->hdr_local_tone_extract_pipeline,
          std::array<id<MTLBuffer>, 2U>{pixel_buffer, hdr_local_log_buffer},
          2U,
          uniforms);
      auto current_source = hdr_local_log_buffer;
      for (const auto radius : gaussian_approximation_radii(
               static_cast<double>(hdr_local_tone_program.radius))) {
        if (radius <= 0) continue;
        const auto blur_uniforms = BlurUniforms{
            .width = width,
            .height = height,
            .radius = radius,
        };
        dispatch_hdr_local(
            impl_->blur_horizontal_pipeline,
            std::array<id<MTLBuffer>, 2U>{
                current_source, hdr_local_scratch_buffer},
            2U,
            blur_uniforms);
        dispatch_hdr_local(
            impl_->blur_vertical_pipeline,
            std::array<id<MTLBuffer>, 2U>{
                hdr_local_scratch_buffer, hdr_local_blur_buffer},
            2U,
            blur_uniforms);
        current_source = hdr_local_blur_buffer;
      }
      dispatch_hdr_local(
          impl_->hdr_local_tone_apply_pipeline,
          std::array<id<MTLBuffer>, 3U>{
              pixel_buffer, hdr_local_log_buffer, hdr_local_blur_buffer},
          3U,
          uniforms);
    }
    if (curve_luts != nullptr) {
      const auto active_mask =
          (curve_luts->parametric.empty() ? 0U : 1U) |
          (curve_luts->master.empty() ? 0U : 2U) |
          (curve_luts->luma.empty() ? 0U : 4U) |
          (curve_luts->red.empty() ? 0U : 8U) |
          (curve_luts->green.empty() ? 0U : 16U) |
          (curve_luts->blue.empty() ? 0U : 32U);
      const auto curve_uniforms = CurveStageUniforms{
          .luminance_red = curve_luts->luminance_coefficients[0],
          .luminance_green = curve_luts->luminance_coefficients[1],
          .luminance_blue = curve_luts->luminance_coefficients[2],
          .output_headroom = curve_luts->output_headroom,
          .sample_count = CompiledCurveStageLuts::kSampleCount,
          .pixel_count = static_cast<std::uint32_t>(pixel_count),
          .active_mask = active_mask,
      };
      id<MTLComputeCommandEncoder> curve_encoder =
          [command_buffer computeCommandEncoder];
      [curve_encoder setComputePipelineState:impl_->curve_stage_pipeline];
      [curve_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
      [curve_encoder setBuffer:curve_lut_buffer offset:0 atIndex:1];
      [curve_encoder setBytes:&curve_uniforms
                       length:sizeof(curve_uniforms)
                      atIndex:2];
      auto curve_group_size =
          impl_->curve_stage_pipeline.maxTotalThreadsPerThreadgroup;
      curve_group_size = std::min<NSUInteger>(curve_group_size, 256U);
      [curve_encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
               threadsPerThreadgroup:MTLSizeMake(curve_group_size, 1U, 1U)];
      [curve_encoder endEncoding];
      ++kernel_dispatch_count;
    }
    if (look_program != nullptr) {
      const auto look_uniforms = make_look_stage_uniforms(
          *look_program, static_cast<std::uint32_t>(pixel_count));
      id<MTLComputeCommandEncoder> look_encoder =
          [command_buffer computeCommandEncoder];
      [look_encoder setComputePipelineState:impl_->look_stage_pipeline];
      [look_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
      [look_encoder setBytes:&look_uniforms
                      length:sizeof(look_uniforms)
                     atIndex:1];
      auto look_group_size =
          impl_->look_stage_pipeline.maxTotalThreadsPerThreadgroup;
      look_group_size = std::min<NSUInteger>(look_group_size, 256U);
      [look_encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
              threadsPerThreadgroup:MTLSizeMake(look_group_size, 1U, 1U)];
      [look_encoder endEncoding];
      ++kernel_dispatch_count;
    }
    if (user_lut_program != nullptr) {
      for (auto index = std::size_t{0U};
           index < user_lut_program->luts.size(); ++index) {
        const auto& user_lut = user_lut_program->luts[index];
        const auto user_lut_uniforms = make_user_lut_stage_uniforms(
            user_lut, static_cast<std::uint32_t>(pixel_count));
        id<MTLComputeCommandEncoder> user_lut_encoder =
            [command_buffer computeCommandEncoder];
        [user_lut_encoder
            setComputePipelineState:impl_->user_lut_stage_pipeline];
        [user_lut_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
        [user_lut_encoder
            setBuffer:user_lut_buffers[index] offset:0 atIndex:1];
        [user_lut_encoder setBytes:&user_lut_uniforms
                            length:sizeof(user_lut_uniforms)
                           atIndex:2];
        auto user_lut_group_size =
            impl_->user_lut_stage_pipeline.maxTotalThreadsPerThreadgroup;
        user_lut_group_size =
            std::min<NSUInteger>(user_lut_group_size, 256U);
        [user_lut_encoder
              dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
            threadsPerThreadgroup:MTLSizeMake(
                                      user_lut_group_size, 1U, 1U)];
        [user_lut_encoder endEncoding];
        ++kernel_dispatch_count;
      }
    }
    if (state.linear_mask_enabled || state.radial_mask_enabled) {
      const auto mask_uniforms = make_mask_uniforms(state, width, height);
      id<MTLComputeCommandEncoder> mask_encoder = [command_buffer computeCommandEncoder];
      [mask_encoder setComputePipelineState:impl_->mask_pipeline];
      [mask_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
      [mask_encoder setBytes:&mask_uniforms length:sizeof(mask_uniforms) atIndex:1];

      NSUInteger thread_group_size = impl_->mask_pipeline.maxTotalThreadsPerThreadgroup;
      if (thread_group_size > 256) thread_group_size = 256;
      [mask_encoder dispatchThreads:MTLSizeMake(pixel_count, 1, 1)
               threadsPerThreadgroup:MTLSizeMake(thread_group_size, 1, 1)];
      [mask_encoder endEncoding];
      ++kernel_dispatch_count;
    }

    if (apply_color_lut) {
    ColorAdjustmentUniforms lut_uniforms{};
    lut_uniforms.lut_size = lut.size;
    lut_uniforms.width = width;
    lut_uniforms.height = height;

    id<MTLComputeCommandEncoder> lut_encoder = [command_buffer computeCommandEncoder];
    [lut_encoder setComputePipelineState:impl_->lut_pipeline];
    [lut_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
    [lut_encoder setBuffer:lut_buffer offset:0 atIndex:1];
    [lut_encoder setBytes:&lut_uniforms length:sizeof(lut_uniforms) atIndex:2];

    NSUInteger thread_group_size = impl_->lut_pipeline.maxTotalThreadsPerThreadgroup;
    if (thread_group_size > 256) thread_group_size = 256;
    [lut_encoder dispatchThreads:MTLSizeMake(pixel_count, 1, 1)
            threadsPerThreadgroup:MTLSizeMake(thread_group_size, 1, 1)];
    [lut_encoder endEncoding];
    ++kernel_dispatch_count;
    }

    if (apply_fill_layers) {
      auto uniforms = FillLayerUniforms{
          .blend_headroom = fill_layer_program.blend_headroom,
          .layer_count = fill_layer_program.layer_count,
          .width = fill_layer_program.width,
          .height = fill_layer_program.height,
          .output_headroom = fill_layer_program.output_headroom,
          .layer_end = fill_layer_program.layer_count,
          .perceptual_blend_gamut_mode =
              !fill_layer_program.gamut_mapping_enabled ||
                      fill_layer_program.gamut_mapping_policy ==
                          GamutMappingPolicy::Clip ||
                      fill_layer_program.render_intent ==
                          RenderIntent::RelativeColorimetric
                  ? 1U
                  : (fill_layer_program.gamut_mapping_policy ==
                             GamutMappingPolicy::PreserveSaturation
                         ? 2U
                         : 0U),
      };
      for (auto matrix_index = std::size_t{0U}; matrix_index < 9U; ++matrix_index) {
        uniforms.rgb_to_xyz_d65[matrix_index] = static_cast<float>(
            fill_layer_program.rgb_to_xyz_d65.values[matrix_index]);
        uniforms.xyz_d65_to_rgb[matrix_index] = static_cast<float>(
            fill_layer_program.xyz_d65_to_rgb.values[matrix_index]);
      }
      const auto tone_layer = std::find_if(
          fill_layer_program.layers.cbegin(),
          fill_layer_program.layers.cbegin() + fill_layer_program.layer_count,
          [](const auto& layer) {
            return layer.has_tone || layer.has_advanced_tone || layer.has_curves;
          });
      if (tone_layer != fill_layer_program.layers.cbegin() +
                            fill_layer_program.layer_count) {
        const auto tone_index = static_cast<std::size_t>(
            tone_layer - fill_layer_program.layers.cbegin());
        if (tone_layer->has_tone || tone_layer->has_advanced_tone) {
          const auto& tone = tone_layer->has_tone
              ? fill_layer_program.tone_luts[tone_index]
              : fill_layer_program.advanced_tone_luts[tone_index];
          uniforms.luminance_red = tone.luminance_coefficients[0];
          uniforms.luminance_green = tone.luminance_coefficients[1];
          uniforms.luminance_blue = tone.luminance_coefficients[2];
          uniforms.tone_stop_step = tone.stop_step;
          uniforms.output_headroom = tone.output_headroom;
        } else {
          const auto& curves = fill_layer_program.curve_luts[tone_index];
          uniforms.luminance_red = curves.luminance_coefficients[0];
          uniforms.luminance_green = curves.luminance_coefficients[1];
          uniforms.luminance_blue = curves.luminance_coefficients[2];
          uniforms.output_headroom = curves.output_headroom;
        }
      }
      for (auto index = std::size_t{0U};
           index < fill_layer_program.layer_count; ++index) {
        uniforms.layers[index].color = fill_layer_program.layers[index].color;
        uniforms.layers[index].opacity = fill_layer_program.layers[index].opacity;
        uniforms.layers[index].blend_mode =
            fill_layer_program.layers[index].blend_mode;
        uniforms.layers[index].mask_offset =
            fill_layer_program.layers[index].mask_offset;
        uniforms.layers[index].mask_width =
            fill_layer_program.layers[index].mask_width;
        uniforms.layers[index].mask_height =
            fill_layer_program.layers[index].mask_height;
        uniforms.layers[index].mask_inverted =
            fill_layer_program.layers[index].mask_inverted ? 1U : 0U;
        uniforms.layers[index].mask_opacity =
            fill_layer_program.layers[index].mask_opacity;
        uniforms.layers[index].mask_density =
            fill_layer_program.layers[index].mask_density;
        uniforms.layers[index].has_mask =
            fill_layer_program.layers[index].has_mask ? 1U : 0U;
        uniforms.layers[index].clipping_mask =
            fill_layer_program.layers[index].clipping_mask ? 1U : 0U;
        uniforms.layers[index].erase_base_image =
            fill_layer_program.layers[index].erase_base_image ? 1U : 0U;
        uniforms.layers[index].kind = fill_layer_program.layers[index].kind;
        uniforms.layers[index].pixel_offset =
            fill_layer_program.layers[index].pixel_offset;
        uniforms.layers[index].pixel_width =
            fill_layer_program.layers[index].pixel_width;
        uniforms.layers[index].pixel_height =
            fill_layer_program.layers[index].pixel_height;
        uniforms.layers[index].x = fill_layer_program.layers[index].x;
        uniforms.layers[index].y = fill_layer_program.layers[index].y;
        uniforms.layers[index].transform_scale =
            fill_layer_program.layers[index].transform_scale;
        uniforms.layers[index].transform_rotation =
            fill_layer_program.layers[index].transform_rotation;
        uniforms.layers[index].exposure_gain =
            fill_layer_program.layers[index].exposure_gain;
        uniforms.layers[index].tone_offset =
            fill_layer_program.layers[index].tone_offset;
        uniforms.layers[index].has_tone =
            fill_layer_program.layers[index].has_tone ? 1U : 0U;
        uniforms.layers[index].has_white_balance =
            fill_layer_program.layers[index].has_white_balance ? 1U : 0U;
        uniforms.layers[index].white_balance =
            fill_layer_program.layers[index].white_balance;
        uniforms.layers[index].has_look =
            fill_layer_program.layers[index].has_look ? 1U : 0U;
        if (fill_layer_program.layers[index].has_look) {
          const auto& look = fill_layer_program.look_programs[index];
          for (auto matrix_index = std::size_t{0U}; matrix_index < 9U;
               ++matrix_index) {
            uniforms.layers[index].rgb_to_xyz_d65[matrix_index] =
                static_cast<float>(look.rgb_to_xyz_d65.values[matrix_index]);
            uniforms.layers[index].xyz_d65_to_rgb[matrix_index] =
                static_cast<float>(look.xyz_d65_to_rgb.values[matrix_index]);
          }
          uniforms.layers[index].look_luminance = look.luminance_coefficients;
          uniforms.layers[index].saturation_strength = look.saturation_strength;
          uniforms.layers[index].vibrance_strength = look.vibrance_strength;
          uniforms.layers[index].look_output_headroom = look.output_headroom;
        }
        uniforms.layers[index].has_local_chroma =
            fill_layer_program.layers[index].has_local_chroma ? 1U : 0U;
        uniforms.layers[index].hue_shift =
            fill_layer_program.layers[index].hue_shift;
        uniforms.layers[index].saturation_shift =
            fill_layer_program.layers[index].saturation_shift;
        uniforms.layers[index].colorize_hue =
            fill_layer_program.layers[index].colorize_hue;
        uniforms.layers[index].colorize_amount =
            fill_layer_program.layers[index].colorize_amount;
        uniforms.layers[index].advanced_tone_offset =
            fill_layer_program.layers[index].advanced_tone_offset;
        uniforms.layers[index].has_advanced_tone =
            fill_layer_program.layers[index].has_advanced_tone ? 1U : 0U;
        uniforms.layers[index].curve_offsets =
            fill_layer_program.layers[index].curve_offsets;
        uniforms.layers[index].curve_active_mask =
            fill_layer_program.layers[index].curve_active_mask;
        uniforms.layers[index].has_curves =
            fill_layer_program.layers[index].has_curves ? 1U : 0U;
        uniforms.layers[index].has_downstream_look =
            fill_layer_program.layers[index].has_downstream_look ? 1U : 0U;
        uniforms.layers[index].lens_vignette =
            fill_layer_program.layers[index].lens_vignette;
        uniforms.layers[index].dehaze = fill_layer_program.layers[index].dehaze;
      }
      const auto dispatch_buffers = [&](id<MTLComputePipelineState> pipeline,
                                         const auto& buffers,
                                         NSUInteger uniforms_index,
                                         const void* payload,
                                         std::size_t payload_size) {
        id<MTLComputeCommandEncoder> encoder =
            [command_buffer computeCommandEncoder];
        [encoder setComputePipelineState:pipeline];
        for (auto buffer_index = std::size_t{0U};
             buffer_index < buffers.size(); ++buffer_index) {
          [encoder setBuffer:buffers[buffer_index]
                      offset:0
                     atIndex:static_cast<NSUInteger>(buffer_index)];
        }
        if (payload_size > 0U) {
          [encoder setBytes:payload length:payload_size atIndex:uniforms_index];
        }
        auto group_size = std::min<NSUInteger>(
            pipeline.maxTotalThreadsPerThreadgroup, 256U);
        [encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
             threadsPerThreadgroup:MTLSizeMake(group_size, 1U, 1U)];
        [encoder endEncoding];
        ++kernel_dispatch_count;
      };
      const auto dispatch_fill = [&](const FillLayerUniforms& active_uniforms,
                                     id<MTLBuffer> intermediate_buffer) {
        id<MTLBuffer> uniform_buffer = [impl_->device
            newBufferWithBytes:&active_uniforms
                         length:sizeof(active_uniforms)
                        options:MTLResourceStorageModeShared];
        if (uniform_buffer == nil) return false;
        dispatch_buffers(
            impl_->fill_layer_pipeline,
            std::array<id<MTLBuffer>, 9U>{
                pixel_buffer, fill_mask_buffer, layer_pixel_buffer,
                layer_tone_buffer, layer_curve_buffer, layer_look_buffer,
                uniform_buffer, layer_alpha_buffer, intermediate_buffer},
            9U, nullptr, 0U);
        return true;
      };
      const auto box_blur = [&](id<MTLBuffer> input, id<MTLBuffer> output,
                                int radius) {
        const auto blur = BlurUniforms{width, height, radius};
        dispatch_buffers(
            impl_->blur_horizontal_pipeline,
            std::array<id<MTLBuffer>, 2U>{input, spatial_scratch_buffer},
            2U, &blur, sizeof(blur));
        dispatch_buffers(
            impl_->blur_vertical_pipeline,
            std::array<id<MTLBuffer>, 2U>{spatial_scratch_buffer, output},
            2U, &blur, sizeof(blur));
      };
      const auto guided_blur = [&](id<MTLBuffer> input, id<MTLBuffer> output,
                                   int radius, float epsilon) {
        const auto guided = GuidedFilterUniforms{
            .pixel_count = static_cast<std::uint32_t>(pixel_count),
            .epsilon = epsilon};
        box_blur(input, detail_lightness_buffer, radius);
        dispatch_buffers(
            impl_->guided_square_pipeline,
            std::array<id<MTLBuffer>, 2U>{input, spatial_haze_buffer},
            2U, &guided, sizeof(guided));
        box_blur(spatial_haze_buffer, detail_chroma_a_buffer, radius);
        dispatch_buffers(
            impl_->guided_coefficients_pipeline,
            std::array<id<MTLBuffer>, 5U>{
                input, detail_lightness_buffer, detail_chroma_a_buffer,
                detail_chroma_b_buffer, detail_blur_a_buffer},
            5U, &guided, sizeof(guided));
        box_blur(detail_chroma_b_buffer, detail_blur_b_buffer, radius);
        box_blur(detail_blur_a_buffer, spatial_haze_buffer, radius);
        dispatch_buffers(
            impl_->guided_compose_pipeline,
            std::array<id<MTLBuffer>, 4U>{
                input, detail_blur_b_buffer, spatial_haze_buffer, output},
            4U, &guided, sizeof(guided));
      };
      const auto apply_layer_spatial = [&](const CompiledFillLayer& layer,
                                           id<MTLBuffer> target_buffer) {
        const auto spatial = RetainedSpatialDetailUniforms{
            .luminance_red = static_cast<float>(
                fill_layer_program.rgb_to_xyz_native.values[3]),
            .luminance_green = static_cast<float>(
                fill_layer_program.rgb_to_xyz_native.values[4]),
            .luminance_blue = static_cast<float>(
                fill_layer_program.rgb_to_xyz_native.values[5]),
            .texture_strength = layer.texture,
            .clarity_strength = layer.clarity,
            .dehaze_strength = 0.0F,
            .output_headroom = fill_layer_program.output_headroom,
            .width = fill_layer_program.width,
            .height = fill_layer_program.height,
            .active_mask =
                (std::abs(layer.texture) > 1.0e-6F ? 1U : 0U) | 2U};
        dispatch_buffers(
            impl_->retained_spatial_luminance_pipeline,
            std::array<id<MTLBuffer>, 2U>{
                target_buffer, spatial_luminance_buffer},
            2U, &spatial, sizeof(spatial));
        if (std::abs(layer.dehaze) > 1.0e-9F) {
          uniforms.source_only = 3U;
          if (!dispatch_fill(uniforms, target_buffer)) return false;
        }
        if ((spatial.active_mask & 1U) != 0U) guided_blur(
            spatial_luminance_buffer, spatial_texture_buffer, 2, 0.00045F);
        guided_blur(
            spatial_luminance_buffer, spatial_clarity_buffer, 8, 0.0018F);
        dispatch_buffers(
            impl_->retained_spatial_detail_pipeline,
            std::array<id<MTLBuffer>, 5U>{
                target_buffer, spatial_luminance_buffer,
                spatial_texture_buffer, spatial_clarity_buffer,
                spatial_haze_buffer},
            5U, &spatial, sizeof(spatial));
        return true;
      };
      const auto apply_layer_fine = [&](std::size_t layer_index,
                                        id<MTLBuffer> target_buffer) {
        const auto& program = fill_layer_program.fine_detail_programs[layer_index];
        auto detail = RetainedFineDetailUniforms{
            .sharpen_strength = program.sharpen_strength,
            .sharpen_gain = program.sharpen_gain,
            .sharpen_mask_strength = program.sharpen_mask_strength,
            .luminance_nr_strength = program.luminance_nr_strength,
            .color_nr_strength = program.color_nr_strength,
            .width = program.width, .height = program.height,
            .active_mask = program.active_mask};
        for (auto matrix_index = std::size_t{0U}; matrix_index < 9U; ++matrix_index) {
          detail.rgb_to_xyz_d65[matrix_index] = static_cast<float>(
              program.rgb_to_xyz_d65.values[matrix_index]);
          detail.xyz_d65_to_rgb[matrix_index] = static_cast<float>(
              program.xyz_d65_to_rgb.values[matrix_index]);
        }
        dispatch_buffers(
            impl_->retained_detail_extract_pipeline,
            std::array<id<MTLBuffer>, 4U>{
                target_buffer, detail_lightness_buffer,
                detail_chroma_a_buffer, detail_chroma_b_buffer},
            4U, &detail, sizeof(detail));
        const auto blur_fine = [&](id<MTLBuffer> input, id<MTLBuffer> output,
                                   int radius) {
          auto source_buffer = input;
          for (const auto pass_radius : gaussian_approximation_radii(radius)) {
            if (pass_radius <= 0) continue;
            box_blur(source_buffer, output, pass_radius);
            source_buffer = output;
          }
        };
        if ((program.active_mask & CompiledFineDetailProgram::kSharpen) != 0U) {
          blur_fine(detail_lightness_buffer, detail_blur_a_buffer,
                    static_cast<int>(program.sharpen_radius));
          blur_fine(detail_lightness_buffer, detail_blur_b_buffer,
                    static_cast<int>(program.sharpen_edge_radius));
          dispatch_buffers(
              impl_->retained_detail_sharpen_pipeline,
              std::array<id<MTLBuffer>, 3U>{
                  detail_lightness_buffer, detail_blur_a_buffer,
                  detail_blur_b_buffer},
              3U, &detail, sizeof(detail));
        }
        if ((program.active_mask &
             CompiledFineDetailProgram::kLuminanceNoiseReduction) != 0U) {
          blur_fine(detail_lightness_buffer, detail_blur_a_buffer, 2);
          blur_fine(detail_lightness_buffer, detail_blur_b_buffer, 5);
          dispatch_buffers(
              impl_->retained_detail_luma_nr_pipeline,
              std::array<id<MTLBuffer>, 3U>{
                  detail_lightness_buffer, detail_blur_a_buffer,
                  detail_blur_b_buffer},
              3U, &detail, sizeof(detail));
        }
        if ((program.active_mask &
             CompiledFineDetailProgram::kColorNoiseReduction) != 0U) {
          blur_fine(detail_chroma_a_buffer, detail_blur_a_buffer, 3);
          blur_fine(detail_chroma_b_buffer, detail_blur_b_buffer, 3);
          dispatch_buffers(
              impl_->retained_detail_color_nr_pipeline,
              std::array<id<MTLBuffer>, 4U>{
                  detail_chroma_a_buffer, detail_chroma_b_buffer,
                  detail_blur_a_buffer, detail_blur_b_buffer},
              4U, &detail, sizeof(detail));
        }
        dispatch_buffers(
            impl_->retained_detail_compose_pipeline,
            std::array<id<MTLBuffer>, 4U>{
                target_buffer, detail_lightness_buffer,
                detail_chroma_a_buffer, detail_chroma_b_buffer},
            4U, &detail, sizeof(detail));
      };
      const auto apply_layer_geometry_program = [&](std::size_t layer_index) {
        const auto& program = fill_layer_program.geometry_programs[layer_index];
        const auto geometry_uniforms = GeometryStageUniforms{
            .distortion_strength = program.distortion_strength,
            .chromatic_aberration_strength =
                program.chromatic_aberration_strength,
            .vertical_perspective = program.vertical_perspective,
            .horizontal_perspective = program.horizontal_perspective,
            .transform_rotation = program.transform_rotation,
            .transform_scale = program.transform_scale,
            .transform_skew_x = program.transform_skew_x,
            .transform_skew_y = program.transform_skew_y,
            .liquify_strength = program.liquify_strength,
            .liquify_center_x = program.liquify_center_x,
            .liquify_center_y = program.liquify_center_y,
            .liquify_radius = program.liquify_radius,
            .center_x = program.center_x,
            .center_y = program.center_y,
            .maximum_radius = program.maximum_radius,
            .width = program.width,
            .height = program.height,
            .content_aware_crop_fill =
                program.content_aware_crop_fill ? 1U : 0U,
        };
        dispatch_buffers(
            impl_->geometry_stage_pipeline,
            std::array<id<MTLBuffer>, 2U>{
                layer_intermediate_buffer, geometry_buffer},
            2U, &geometry_uniforms, sizeof(geometry_uniforms));
      };
      const auto apply_layer_user_luts = [&](
          std::size_t layer_index, id<MTLBuffer> target_buffer) {
        const auto& program = fill_layer_program.user_lut_programs[layer_index];
        for (auto lut_index = std::size_t{0U};
             lut_index < program.luts.size(); ++lut_index) {
          const auto lut_uniforms = make_user_lut_stage_uniforms(
              program.luts[lut_index],
              static_cast<std::uint32_t>(pixel_count));
          dispatch_buffers(
              impl_->user_lut_stage_pipeline,
              std::array<id<MTLBuffer>, 2U>{
                  target_buffer, layer_user_lut_buffers[layer_index][lut_index]},
              2U, &lut_uniforms, sizeof(lut_uniforms));
        }
      };
      if (!apply_layer_user_lut && !apply_layer_geometry &&
          !apply_layer_spatial_detail &&
          !apply_layer_fine_detail) {
        if (!dispatch_fill(uniforms, layer_intermediate_buffer)) {
          fail("fused_fill_layer_uniform_buffer_allocation_failed");
          return {};
        }
      } else {
        for (auto layer_index = std::uint32_t{0U};
             layer_index < fill_layer_program.layer_count; ++layer_index) {
          uniforms.layer_begin = layer_index;
          uniforms.layer_end = layer_index + 1U;
          const auto& layer = fill_layer_program.layers[layer_index];
          if (!layer.has_user_lut && !layer.has_geometry &&
              !layer.has_spatial_detail &&
              !layer.has_fine_detail) {
            uniforms.source_only = uniforms.composite_only = 0U;
            if (!dispatch_fill(uniforms, layer_intermediate_buffer)) return {};
            continue;
          }
          uniforms.source_only = 1U; uniforms.composite_only = 0U;
          if (!dispatch_fill(uniforms, layer_intermediate_buffer)) return {};
          auto layer_source_buffer = layer_intermediate_buffer;
          if (layer.has_user_lut) {
            apply_layer_user_luts(layer_index, layer_source_buffer);
          }
          if (std::abs(layer.lens_vignette) > 1.0e-6F) {
            uniforms.source_only = 2U;
            if (!dispatch_fill(uniforms, layer_source_buffer)) return {};
          }
          if (layer.has_geometry) {
            apply_layer_geometry_program(layer_index);
            layer_source_buffer = geometry_buffer;
          }
          if (layer.has_spatial_detail) {
            if (!apply_layer_spatial(layer, layer_source_buffer)) return {};
          } else if (std::abs(layer.dehaze) > 1.0e-9F) {
            uniforms.source_only = 3U;
            if (!dispatch_fill(uniforms, layer_source_buffer)) return {};
          }
          if (layer.has_fine_detail) {
            apply_layer_fine(layer_index, layer_source_buffer);
          }
          uniforms.source_only = 0U; uniforms.composite_only = 1U;
          if (!dispatch_fill(uniforms, layer_source_buffer)) return {};
        }
      }
    }

    if (apply_spatial_detail) {
      const auto spatial_uniforms = RetainedSpatialDetailUniforms{
          .luminance_red =
              spatial_detail_program.luminance_coefficients[0],
          .luminance_green =
              spatial_detail_program.luminance_coefficients[1],
          .luminance_blue =
              spatial_detail_program.luminance_coefficients[2],
          .texture_strength = spatial_detail_program.texture_strength,
          .clarity_strength = spatial_detail_program.clarity_strength,
          .dehaze_strength = spatial_detail_program.dehaze_strength,
          .output_headroom = spatial_detail_program.output_headroom,
          .width = spatial_detail_program.width,
          .height = spatial_detail_program.height,
          .active_mask = spatial_detail_program.active_mask,
      };
      const auto dispatch_spatial = [&](id<MTLComputePipelineState> pipeline,
                                        const auto& encode_buffers,
                                        NSUInteger uniforms_index,
                                        const void* uniforms,
                                        std::size_t uniforms_size) {
        id<MTLComputeCommandEncoder> encoder =
            [command_buffer computeCommandEncoder];
        [encoder setComputePipelineState:pipeline];
        for (auto index = std::size_t{0U}; index < encode_buffers.size();
             ++index) {
          [encoder setBuffer:encode_buffers[index]
                      offset:0
                     atIndex:static_cast<NSUInteger>(index)];
        }
        [encoder setBytes:uniforms
                   length:uniforms_size
                  atIndex:uniforms_index];
        auto group_size = pipeline.maxTotalThreadsPerThreadgroup;
        group_size = std::min<NSUInteger>(group_size, 256U);
        [encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
             threadsPerThreadgroup:MTLSizeMake(group_size, 1U, 1U)];
        [encoder endEncoding];
        ++kernel_dispatch_count;
      };
      dispatch_spatial(
          impl_->retained_spatial_luminance_pipeline,
          std::array<id<MTLBuffer>, 2U>{
              pixel_buffer, spatial_luminance_buffer},
          2U,
          &spatial_uniforms,
          sizeof(spatial_uniforms));
      const auto blur_spatial = [&](int radius,
                                    id<MTLBuffer> destination,
                                    std::int64_t* dispatch_telemetry) {
        const auto blur_uniforms = BlurUniforms{
            .width = width,
            .height = height,
            .radius = radius,
        };
        dispatch_spatial(
            impl_->blur_horizontal_pipeline,
            std::array<id<MTLBuffer>, 2U>{
                spatial_luminance_buffer, spatial_scratch_buffer},
            2U,
            &blur_uniforms,
            sizeof(blur_uniforms));
        dispatch_spatial(
            impl_->blur_vertical_pipeline,
            std::array<id<MTLBuffer>, 2U>{
                spatial_scratch_buffer, destination},
            2U,
            &blur_uniforms,
            sizeof(blur_uniforms));
        if (dispatch_telemetry != nullptr) *dispatch_telemetry += 2;
      };
      if ((spatial_detail_program.active_mask &
           CompiledSpatialDetailProgram::kTexture) != 0U) {
        blur_spatial(
            2,
            spatial_texture_buffer,
            telemetry != nullptr
                ? &telemetry->gpu_spatial_texture_blur_dispatch_count
                : nullptr);
      }
      if ((spatial_detail_program.active_mask &
           CompiledSpatialDetailProgram::kClarity) != 0U) {
        blur_spatial(
            8,
            spatial_clarity_buffer,
            telemetry != nullptr
                ? &telemetry->gpu_spatial_clarity_blur_dispatch_count
                : nullptr);
      }
      if ((spatial_detail_program.active_mask &
           CompiledSpatialDetailProgram::kDehaze) != 0U) {
        blur_spatial(
            20,
            spatial_haze_buffer,
            telemetry != nullptr
                ? &telemetry->gpu_spatial_haze_blur_dispatch_count
                : nullptr);
      }
      dispatch_spatial(
          impl_->retained_spatial_detail_pipeline,
          std::array<id<MTLBuffer>, 5U>{
              pixel_buffer,
              spatial_luminance_buffer,
              spatial_texture_buffer,
              spatial_clarity_buffer,
              spatial_haze_buffer},
          5U,
          &spatial_uniforms,
          sizeof(spatial_uniforms));
    }

    if (apply_fine_detail) {
      auto detail_uniforms = RetainedFineDetailUniforms{
          .sharpen_strength = fine_detail_program.sharpen_strength,
          .sharpen_gain = fine_detail_program.sharpen_gain,
          .sharpen_mask_strength =
              fine_detail_program.sharpen_mask_strength,
          .luminance_nr_strength =
              fine_detail_program.luminance_nr_strength,
          .color_nr_strength = fine_detail_program.color_nr_strength,
          .width = fine_detail_program.width,
          .height = fine_detail_program.height,
          .active_mask = fine_detail_program.active_mask,
      };
      for (auto index = std::size_t{0U}; index < 9U; ++index) {
        detail_uniforms.rgb_to_xyz_d65[index] = static_cast<float>(
            fine_detail_program.rgb_to_xyz_d65.values[index]);
        detail_uniforms.xyz_d65_to_rgb[index] = static_cast<float>(
            fine_detail_program.xyz_d65_to_rgb.values[index]);
      }
      const auto dispatch_detail = [&](id<MTLComputePipelineState> pipeline,
                                       const auto& encode_buffers,
                                       NSUInteger uniforms_index,
                                       const void* uniforms,
                                       std::size_t uniforms_size) {
        id<MTLComputeCommandEncoder> encoder =
            [command_buffer computeCommandEncoder];
        [encoder setComputePipelineState:pipeline];
        for (auto index = std::size_t{0U}; index < encode_buffers.size();
             ++index) {
          [encoder setBuffer:encode_buffers[index]
                      offset:0
                     atIndex:static_cast<NSUInteger>(index)];
        }
        [encoder setBytes:uniforms
                   length:uniforms_size
                  atIndex:uniforms_index];
        auto group_size = pipeline.maxTotalThreadsPerThreadgroup;
        group_size = std::min<NSUInteger>(group_size, 256U);
        [encoder dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
             threadsPerThreadgroup:MTLSizeMake(group_size, 1U, 1U)];
        [encoder endEncoding];
        ++kernel_dispatch_count;
      };
      dispatch_detail(
          impl_->retained_detail_extract_pipeline,
          std::array<id<MTLBuffer>, 4U>{
              pixel_buffer,
              detail_lightness_buffer,
              detail_chroma_a_buffer,
              detail_chroma_b_buffer},
          4U,
          &detail_uniforms,
          sizeof(detail_uniforms));
      const auto blur_detail = [&](id<MTLBuffer> source,
                                   id<MTLBuffer> destination,
                                   int radius) {
        auto current_source = source;
        for (const auto pass_radius :
             gaussian_approximation_radii(static_cast<double>(radius))) {
          if (pass_radius <= 0) continue;
          const auto blur_uniforms = BlurUniforms{
              .width = width,
              .height = height,
              .radius = pass_radius,
          };
          dispatch_detail(
              impl_->blur_horizontal_pipeline,
              std::array<id<MTLBuffer>, 2U>{
                  current_source, detail_scratch_buffer},
              2U,
              &blur_uniforms,
              sizeof(blur_uniforms));
          dispatch_detail(
              impl_->blur_vertical_pipeline,
              std::array<id<MTLBuffer>, 2U>{
                  detail_scratch_buffer, destination},
              2U,
              &blur_uniforms,
              sizeof(blur_uniforms));
          current_source = destination;
        }
      };
      if ((fine_detail_program.active_mask &
           CompiledFineDetailProgram::kSharpen) != 0U) {
        blur_detail(
            detail_lightness_buffer,
            detail_blur_a_buffer,
            static_cast<int>(fine_detail_program.sharpen_radius));
        blur_detail(
            detail_lightness_buffer,
            detail_blur_b_buffer,
            static_cast<int>(fine_detail_program.sharpen_edge_radius));
        dispatch_detail(
            impl_->retained_detail_sharpen_pipeline,
            std::array<id<MTLBuffer>, 3U>{
                detail_lightness_buffer,
                detail_blur_a_buffer,
                detail_blur_b_buffer},
            3U,
            &detail_uniforms,
            sizeof(detail_uniforms));
      }
      if ((fine_detail_program.active_mask &
           CompiledFineDetailProgram::kLuminanceNoiseReduction) != 0U) {
        blur_detail(detail_lightness_buffer, detail_blur_a_buffer, 2);
        blur_detail(detail_lightness_buffer, detail_blur_b_buffer, 5);
        dispatch_detail(
            impl_->retained_detail_luma_nr_pipeline,
            std::array<id<MTLBuffer>, 3U>{
                detail_lightness_buffer,
                detail_blur_a_buffer,
                detail_blur_b_buffer},
            3U,
            &detail_uniforms,
            sizeof(detail_uniforms));
      }
      if ((fine_detail_program.active_mask &
           CompiledFineDetailProgram::kColorNoiseReduction) != 0U) {
        blur_detail(detail_chroma_a_buffer, detail_blur_a_buffer, 3);
        blur_detail(detail_chroma_b_buffer, detail_blur_b_buffer, 3);
        dispatch_detail(
            impl_->retained_detail_color_nr_pipeline,
            std::array<id<MTLBuffer>, 4U>{
                detail_chroma_a_buffer,
                detail_chroma_b_buffer,
                detail_blur_a_buffer,
                detail_blur_b_buffer},
            4U,
            &detail_uniforms,
            sizeof(detail_uniforms));
      }
      dispatch_detail(
          impl_->retained_detail_compose_pipeline,
          std::array<id<MTLBuffer>, 4U>{
              pixel_buffer,
              detail_lightness_buffer,
              detail_chroma_a_buffer,
              detail_chroma_b_buffer},
          4U,
          &detail_uniforms,
          sizeof(detail_uniforms));
    }

    id<MTLBuffer> final_pixel_buffer = pixel_buffer;
    if (apply_geometry) {
      const auto geometry_uniforms = GeometryStageUniforms{
          .distortion_strength = geometry_program.distortion_strength,
          .chromatic_aberration_strength =
              geometry_program.chromatic_aberration_strength,
          .vertical_perspective =
              geometry_program.vertical_perspective,
          .horizontal_perspective =
              geometry_program.horizontal_perspective,
          .transform_rotation = geometry_program.transform_rotation,
          .transform_scale = geometry_program.transform_scale,
          .transform_skew_x = geometry_program.transform_skew_x,
          .transform_skew_y = geometry_program.transform_skew_y,
          .liquify_strength = geometry_program.liquify_strength,
          .liquify_center_x = geometry_program.liquify_center_x,
          .liquify_center_y = geometry_program.liquify_center_y,
          .liquify_radius = geometry_program.liquify_radius,
          .center_x = geometry_program.center_x,
          .center_y = geometry_program.center_y,
          .maximum_radius = geometry_program.maximum_radius,
          .width = geometry_program.width,
          .height = geometry_program.height,
          .content_aware_crop_fill =
              geometry_program.content_aware_crop_fill ? 1U : 0U,
      };
      id<MTLComputeCommandEncoder> geometry_encoder =
          [command_buffer computeCommandEncoder];
      [geometry_encoder
          setComputePipelineState:impl_->geometry_stage_pipeline];
      [geometry_encoder setBuffer:pixel_buffer offset:0 atIndex:0];
      [geometry_encoder setBuffer:geometry_buffer offset:0 atIndex:1];
      [geometry_encoder setBytes:&geometry_uniforms
                          length:sizeof(geometry_uniforms)
                         atIndex:2];
      auto geometry_group_size =
          impl_->geometry_stage_pipeline.maxTotalThreadsPerThreadgroup;
      geometry_group_size =
          std::min<NSUInteger>(geometry_group_size, 256U);
      [geometry_encoder
            dispatchThreads:MTLSizeMake(pixel_count, 1U, 1U)
          threadsPerThreadgroup:MTLSizeMake(
                                    geometry_group_size, 1U, 1U)];
      [geometry_encoder endEncoding];
      final_pixel_buffer = geometry_buffer;
      ++kernel_dispatch_count;
    }

    id<MTLSharedEvent> ready_event = [impl_->device newSharedEvent];
    if (ready_event == nil) {
      fail("fused_masks_color_lut_shared_event_unavailable");
      return {};
    }
    [command_buffer encodeSignalEvent:ready_event value:1U];
    [command_buffer addCompletedHandler:^(id<MTLCommandBuffer> completed) {
      if (completed.status != MTLCommandBufferStatusCompleted &&
          ready_event.signaledValue < 1U) {
        ready_event.signaledValue = 1U;
      }
    }];
    if (cancellation.cancelled()) {
      fail("fused_masks_color_lut_cancelled");
      return {};
    }
    [command_buffer commit];
    auto surface_impl = std::make_shared<MetalWorkingSurface::Impl>();
    surface_impl->pixel_buffer = final_pixel_buffer;
    surface_impl->producer_command_buffer = command_buffer;
    surface_impl->ready_event = ready_event;
    surface_impl->descriptor = descriptor;
    surface_impl->device_registry_id =
        static_cast<std::uint64_t>(impl_->device.registryID);
    surface_impl->ready_event_value = 1U;
    surface_impl->byte_size = static_cast<std::uint64_t>(buffer_size);
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason.clear();
      telemetry->gpu_cpu_to_gpu_bytes +=
          static_cast<std::int64_t>(
              buffer_size +
              lut_upload_bytes +
              tone_lut_upload_bytes +
              curve_lut_upload_bytes +
              fill_mask_upload_bytes +
              layer_pixel_upload_bytes +
              layer_tone_upload_bytes +
              layer_curve_upload_bytes +
              layer_look_upload_bytes);
      telemetry->gpu_command_buffer_count += 1;
      telemetry->gpu_kernel_dispatch_count += kernel_dispatch_count;
    }
    return std::shared_ptr<const MetalWorkingSurface>(
        new MetalWorkingSurface(std::move(surface_impl)));
  }
}

bool MetalPipelineBackend::apply_masks_and_color_lut(
    std::vector<ColorPixel>* pixels,
    int width,
    int height,
    const ColorAdjustmentState& state,
    const ColorLut3D& lut,
    ColorAdjustmentTelemetry* telemetry,
    CancellationToken cancellation) {
  if (pixels == nullptr) {
    if (telemetry != nullptr) {
      telemetry->gpu_fallback_reason = "invalid_fused_masks_color_lut_request";
    }
    return false;
  }
  const auto descriptor = RenderSurfaceDescriptor{
      .pixel_encoding = RenderPixelEncoding::SceneLinearFloat,
      .color_domain = RenderColorDomain::WorkingScene,
      .range = RenderRangeModel::SceneExtended,
      .alpha = RenderAlphaModel::Straight,
      .color_space_identity = "metal-working-compatibility",
      .transfer_identity = "linear",
      .width = static_cast<std::uint32_t>(std::max(width, 0)),
      .height = static_cast<std::uint32_t>(std::max(height, 0)),
  };
  const auto surface = publish_masks_and_color_lut_surface(
      *pixels, width, height, state, lut, descriptor, telemetry, cancellation);
  auto materialized = std::vector<ColorPixel>{};
  if (surface == nullptr || !surface->copy_pixels(&materialized, cancellation)) {
    if (telemetry != nullptr && telemetry->gpu_fallback_reason.empty()) {
      telemetry->gpu_fallback_reason = cancellation.cancelled()
                                           ? "fused_masks_color_lut_cancelled"
                                           : "fused_masks_color_lut_command_buffer_failed";
    }
    return false;
  }
  *pixels = std::move(materialized);
  if (telemetry != nullptr) {
    telemetry->gpu_gpu_to_cpu_bytes +=
        static_cast<std::int64_t>(surface->byte_size());
  }
  return true;
}

std::vector<float> MetalPipelineBackend::gaussian_approximate_blur(
    const std::vector<float>& input,
    int width,
    int height,
    int radius) {
  if (!available() || input.empty() || width <= 0 || height <= 0 || radius <= 0) {
    return input;
  }

  const auto pixel_count = static_cast<std::size_t>(width * height);
  if (input.size() != pixel_count) {
    return input;
  }

  @autoreleasepool {
    const auto buffer_size = pixel_count * sizeof(float);
    id<MTLBuffer> source_buffer = [impl_->device newBufferWithLength:buffer_size
                                                             options:MTLResourceStorageModeShared];
    id<MTLBuffer> temp_buffer = [impl_->device newBufferWithLength:buffer_size
                                                           options:MTLResourceStorageModeShared];
    if (!source_buffer || !temp_buffer) {
      return input;
    }

    auto* source_data = static_cast<float*>([source_buffer contents]);
    std::copy(input.begin(), input.end(), source_data);

    id<MTLCommandBuffer> command_buffer = [impl_->command_queue commandBuffer];
    if (!command_buffer) {
      return input;
    }

    const auto dispatch_pass = [&](id<MTLComputePipelineState> pipeline,
                                   id<MTLBuffer> in_buffer,
                                   id<MTLBuffer> out_buffer,
                                   const BlurUniforms& uniforms) {
      id<MTLComputeCommandEncoder> encoder = [command_buffer computeCommandEncoder];
      [encoder setComputePipelineState:pipeline];
      [encoder setBuffer:in_buffer offset:0 atIndex:0];
      [encoder setBuffer:out_buffer offset:0 atIndex:1];
      [encoder setBytes:&uniforms length:sizeof(uniforms) atIndex:2];

      NSUInteger thread_group_size = pipeline.maxTotalThreadsPerThreadgroup;
      if (thread_group_size > 256) thread_group_size = 256;
      MTLSize grid_size = MTLSizeMake(pixel_count, 1, 1);
      MTLSize group_size = MTLSizeMake(thread_group_size, 1, 1);
      [encoder dispatchThreads:grid_size threadsPerThreadgroup:group_size];
      [encoder endEncoding];
    };

    id<MTLBuffer> current_input = source_buffer;
    id<MTLBuffer> current_output = temp_buffer;
    for (const auto pass_radius : gaussian_approximation_radii(static_cast<double>(radius))) {
      if (pass_radius <= 0) {
        continue;
      }

      const BlurUniforms uniforms{
          .width = width,
          .height = height,
          .radius = pass_radius,
      };
      dispatch_pass(impl_->blur_horizontal_pipeline, current_input, current_output, uniforms);
      std::swap(current_input, current_output);
      dispatch_pass(impl_->blur_vertical_pipeline, current_input, current_output, uniforms);
      std::swap(current_input, current_output);
    }
    [command_buffer commit];
    [command_buffer waitUntilCompleted];

    std::vector<float> output(pixel_count, 0.0F);
    const auto* result_data = static_cast<const float*>([current_input contents]);
    std::copy(result_data, result_data + pixel_count, output.begin());
    return output;
  }
}

MetalPipelineBackend& shared_metal_pipeline_backend() {
  static MetalPipelineBackend backend;
  return backend;
}

}  // namespace photo_editor::pipeline::metal
